export interface Pattern {
  id: string;
  name: string;
  pricePerMeter: number; // Base price for printing, excluding rhinestone cost
  rhinestonesPerMeter: number;
  image?: string; // Base64 string
  defaultRhinestoneId?: string;
}

export interface PatternDetail {
  id: string; // Unique ID for this specific entry in a job
  patternName: string;
  fabricLength: number;
  pricePerMeter: number; // Price at the time of job creation
}

export interface Job {
  id: string;
  name: string;
  price: number; // Final price after discount, calculated from patternDetails
  paidAmount: number;
  createdAt: string; // ISO string format
  patternDetails: PatternDetail[];
  photos?: string[]; // Array of Base64 strings
  estimatedTimeMinutes?: number;
  estimatedCost?: number; // Newly added for cost calculation
  discountAmount?: number;
  notes?: string;
  wastedFabricLength?: number;
  fabricType?: string;
  fabricColor?: string;
  deadline?: string; // ISO string format
  personInCharge?: string;
  rhinestoneId?: string; // ID of the rhinestone type used for this job
}

export interface Customer {
  id: string;
  name: string;
  jobs: Job[];
  phone?: string;
  contactPerson?: string;
  address?: string;
  location?: {
    lat: number;
    lng: number;
  };
}

export interface Task {
  id:string;
  text: string;
  completed: boolean;
  createdAt: string; // ISO string format
  dueDate?: string; // ISO string format for reminders
  locationName?: string;
  locationCoords?: {
    lat: number;
    lng: number;
  };
  notified?: boolean; // To prevent spamming notifications
}

export interface Rhinestone {
  id: string;
  name: string;
  costPerGross: number;
  weightGramsPerGross: number;
  image?: string; // Base64 string
}

export interface Settings {
    electricityCostKwh: number;
    machinePowerWatt: number;
    rhinestones: Rhinestone[];
    companyName: string;
    companyAddress: string;
    companyPhoneNumbers: string[];
    companyEmail: string;
    companyTaxNumber: string;
    companyLogo?: string; // Base64 string
    minutesPer100Meters: number;
    notificationLeadTimeHours: number;
    requirePasswordForDelete: boolean;
    confirmationPassword?: string;
}

export interface Advance {
  id: string;
  amount: number;
  date: string; // ISO string format
  description?: string;
}

export interface Employee {
  id: string;
  name: string;
  advances: Advance[];
}


export type View = 'home' | 'assistant' | 'customers' | 'customerDetail' | 'patterns' | 'settings' | 'advances';

import React, { useState, useEffect, useRef } from 'react';
import type { Customer, Task, View, Pattern, Settings, Rhinestone, Employee } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';
import CustomerListScreen from './components/CustomerListScreen';
import TaskListScreen from './components/TaskListScreen';
import PatternManagementScreen from './components/PatternManagementScreen';
import HomeScreen from './components/HomeScreen';
import SplashScreen from './components/SplashScreen';
import { CustomersIcon, TasksIcon, PatternIcon, HomeIcon, SettingsIcon, MoneyIcon } from './components/Icons';
import { calculateTravelTime } from './services/locationService';
import CustomerDetailScreen from './components/CustomerDetailScreen';
import SettingsScreen from './components/SettingsScreen';
import EmployeeAdvanceScreen from './components/EmployeeAdvanceScreen';

const defaultPatterns: Pattern[] = [
    { id: '1', name: 'Düz Baskı', pricePerMeter: 15, rhinestonesPerMeter: 0.5, image: 'https://via.placeholder.com/150/10B981/FFFFFF?text=Düz' },
    { id: '2', name: 'Desenli A', pricePerMeter: 25, rhinestonesPerMeter: 1.5, image: 'https://via.placeholder.com/150/3B82F6/FFFFFF?text=Desenli+A' },
    { id: '3', name: 'Desenli B (Simli)', pricePerMeter: 35, rhinestonesPerMeter: 2.0, image: 'https://via.placeholder.com/150/F59E0B/FFFFFF?text=Simli' },
    { id: '4', name: 'Özel Tasarım', pricePerMeter: 50, rhinestonesPerMeter: 3.0, image: 'https://via.placeholder.com/150/8B5CF6/FFFFFF?text=Özel' },
];

const defaultRhinestones: Rhinestone[] = [
    { id: '1', name: 'SS10 Kristal', costPerGross: 50, weightGramsPerGross: 30 },
    { id: '2', name: 'SS16 AB', costPerGross: 75, weightGramsPerGross: 60 },
];

const defaultSettings: Settings = {
    electricityCostKwh: 3.5,
    machinePowerWatt: 2000,
    rhinestones: defaultRhinestones,
    companyName: 'AB AYÇAM Tekstil',
    companyAddress: 'Örnek Mah. Sanayi Cad. No:123\n34000, Sanayi Bölgesi / İstanbul',
    companyPhoneNumbers: ['+90 (212) 555 00 00'],
    companyEmail: 'info@abaycam.com',
    companyTaxNumber: '1234567890',
    companyLogo: undefined,
    minutesPer100Meters: 20,
    notificationLeadTimeHours: 24,
    requirePasswordForDelete: true,
    confirmationPassword: '1234',
};


const App: React.FC = () => {
  const [customers, setCustomers] = useLocalStorage<Customer[]>('customers', []);
  const [tasks, setTasks] = useLocalStorage<Task[]>('tasks', []);
  const [patterns, setPatterns] = useLocalStorage<Pattern[]>('patterns', defaultPatterns);
  const [settings, setSettings] = useLocalStorage<Settings>('settings', defaultSettings);
  const [employees, setEmployees] = useLocalStorage<Employee[]>('employees', []);
  const [currentView, setCurrentView] = useState<View>('home');
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);
  const notifiedTaskIds = useRef(new Set<string>());
  const [isLoading, setIsLoading] = useState(true);

  // Splash screen timer
  useEffect(() => {
    const timer = setTimeout(() => {
        setIsLoading(false);
    }, 2000); // 2 seconds

    return () => clearTimeout(timer); // Cleanup timer on unmount
  }, []);

  // One-time migration for settings structure changes
  useEffect(() => {
    setSettings(prevSettings => {
        let needsUpdate = false;
        const newSettings = { ...prevSettings };

        // Migration from single rhinestone values to array
        if (!prevSettings.hasOwnProperty('rhinestones') && prevSettings.hasOwnProperty('rhinestoneCostPerGross')) {
            newSettings.rhinestones = [{
                id: '1',
                name: 'Varsayılan Taş',
                costPerGross: (prevSettings as any).rhinestoneCostPerGross,
                weightGramsPerGross: (prevSettings as any).rhinestoneWeightGramsPerGross
            }];
            delete (newSettings as any).rhinestoneCostPerGross;
            delete (newSettings as any).rhinestoneWeightGramsPerGross;
            needsUpdate = true;
        }

        // Add notificationLeadTimeHours if it doesn't exist
        if (!prevSettings.hasOwnProperty('notificationLeadTimeHours')) {
            newSettings.notificationLeadTimeHours = defaultSettings.notificationLeadTimeHours;
            needsUpdate = true;
        }

        return needsUpdate ? newSettings : prevSettings;
    });
  }, []);

  // Scroll input into view on focus for better mobile keyboard experience
  useEffect(() => {
    const handleFocus = (event: FocusEvent) => {
        const target = event.target as HTMLElement;
        if (
            target.tagName === 'INPUT' ||
            target.tagName === 'TEXTAREA' ||
            target.isContentEditable
        ) {
            setTimeout(() => {
                target.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 300);
        }
    };

    document.addEventListener('focusin', handleFocus);
    return () => {
        document.removeEventListener('focusin', handleFocus);
    };
}, []);


  // Fetch user location once on component mount
  useEffect(() => {
    navigator.geolocation.getCurrentPosition(
      (position) => {
        setUserLocation({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
        });
      },
      (error) => {
        console.error("Error getting user location:", error);
      }
    );
  }, []);

  // Proactive notification logic
  useEffect(() => {
    const interval = setInterval(() => {
      const incompleteTasks = tasks.filter(t => !t.completed && t.dueDate && t.locationCoords && !notifiedTaskIds.current.has(t.id));

      if (incompleteTasks.length > 0 && userLocation) {
         incompleteTasks.forEach(task => {
           const dueDate = new Date(task.dueDate!);
           const now = new Date();

           if(dueDate > now) {
                const travelTimeMinutes = calculateTravelTime(userLocation, task.locationCoords!);
                const PREPARATION_BUFFER_MINUTES = settings.notificationLeadTimeHours * 60;
                const totalLeadTime = (travelTimeMinutes + PREPARATION_BUFFER_MINUTES) * 60 * 1000; // in milliseconds

                const departureTime = new Date(dueDate.getTime() - totalLeadTime);

                if (now >= departureTime) {
                    alert(`HATIRLATMA: "${task.text}" göreviniz için yola çıkma zamanı yaklaşıyor.`);
                    notifiedTaskIds.current.add(task.id);
                }
           }
         });
      }
    }, 60 * 1000); // Check every minute

    return () => clearInterval(interval);
  }, [tasks, userLocation, settings.notificationLeadTimeHours]);

  const handleSelectCustomer = (customerId: string) => {
    setSelectedCustomerId(customerId);
    setCurrentView('customerDetail');
  };

  const handleBackToList = () => {
    setSelectedCustomerId(null);
    setCurrentView('customers');
  };

  const renderContent = () => {
    switch (currentView) {
      case 'home':
        return <HomeScreen customers={customers} tasks={tasks} onNavigate={setCurrentView} />;
      case 'assistant':
        return <TaskListScreen tasks={tasks} setTasks={setTasks} userLocation={userLocation} />;
      case 'customers':
        return (
          <CustomerListScreen
            customers={customers}
            setCustomers={setCustomers}
            onSelectCustomer={handleSelectCustomer}
          />
        );
      case 'customerDetail':
        const selectedCustomer = customers.find(c => c.id === selectedCustomerId);
        if (selectedCustomer) {
          return (
              <CustomerDetailScreen
                customer={selectedCustomer}
                setCustomers={setCustomers}
                onBack={handleBackToList}
                patterns={patterns}
                settings={settings}
              />
          );
        }
        // Fallback if customer not found
        handleBackToList();
        return null;
      case 'advances':
          return <EmployeeAdvanceScreen employees={employees} setEmployees={setEmployees} />;
      case 'settings':
        return <SettingsScreen settings={settings} setSettings={setSettings} patterns={patterns} setPatterns={setPatterns} />;
      default:
        return <HomeScreen customers={customers} tasks={tasks} onNavigate={setCurrentView} />;
    }
  };

  // FIX: Changed icon type from JSX.Element to React.ReactElement to resolve "Cannot find namespace 'JSX'" error.
  const NavButton = ({ view, label, icon }: { view: View, label: string, icon: React.ReactElement }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full pt-2 pb-1 transition-colors duration-200 ${currentView === view || (view === 'customers' && currentView === 'customerDetail') ? 'text-teal-400' : 'text-gray-400 hover:text-teal-300'}`}
    >
      {icon}
      <span className="text-xs mt-1">{label}</span>
    </button>
  );

  return (
    <>
      {isLoading ? (
        <SplashScreen />
      ) : (
        <div className="flex flex-col h-screen font-sans">
          <header className="bg-gray-800 shadow-md p-4 text-center">
            <h1 className="text-2xl font-bold text-teal-400">İş Takip Asistanı</h1>
          </header>
          <main className="flex-grow overflow-y-auto p-4 pb-20 bg-gray-900">
            {renderContent()}
          </main>
          <nav className="fixed bottom-0 left-0 right-0 bg-gray-800 border-t border-gray-700 shadow-lg flex justify-around">
            <NavButton view="home" label="Ana Sayfa" icon={<HomeIcon />} />
            <NavButton view="assistant" label="Asistan" icon={<TasksIcon />} />
            <NavButton view="customers" label="Müşteriler" icon={<CustomersIcon />} />
            <NavButton view="advances" label="Avans" icon={<MoneyIcon />} />
            <NavButton view="settings" label="Ayarlar" icon={<SettingsIcon />} />
          </nav>
        </div>
      )}
    </>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import type { Task } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.warn("API_KEY environment variable not set. Gemini API will not function.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

// This defines the structure we expect from the AI model
interface ParsedTask {
    task: string;
    dueDate: string | null; // ISO 8601 format
    location: string | null;
}

interface UpdatedTask extends Partial<ParsedTask> {
    id: string;
}

interface GeminiResponse {
    newTasks: ParsedTask[];
    updatedTasks: UpdatedTask[];
}


export const parseTasksFromText = async (text: string, existingTasks: Task[], userLocation: { lat: number; lng: number } | null): Promise<GeminiResponse> => {
    if (!API_KEY) {
        // Fallback for when API key is not available
        return {
            newTasks: text.split('\n').map(line => ({
                task: line.trim(),
                dueDate: null,
                location: null
            })).filter(item => item.task.length > 0),
            updatedTasks: []
        };
    }

    try {
        const currentDate = new Date().toISOString();
        // Only send relevant info to save tokens
        const simplifiedExistingTasks = existingTasks.map(t => ({ id: t.id, text: t.text, dueDate: t.dueDate, locationName: t.locationName }));

        const systemInstruction = `Sen, tekstil baskı sektöründe faaliyet gösteren üst düzey bir şirketin elit, proaktif ve akıllı yönetici asistanısın. Görevin, kullanıcının yeni metin girdisini ve MEVCUT GÖREV LİSTESİNİ analiz etmektir.

Mevcut tarih ve saat: ${currentDate}
Mevcut Görev Listesi: ${JSON.stringify(simplifiedExistingTasks)}
${userLocation ? `Kullanıcının mevcut konumu (enlem, boylam): ${userLocation.lat}, ${userLocation.lng}` : ''}

Kesinlikle uyman gereken kurallar:
1.  **Analiz ve Karar Verme:**
    *   Kullanıcının yeni girdisini oku.
    *   Bu girdinin mevcut görev listesindeki bir görevle ilgili olup olmadığını belirle. Örneğin, "patates de al" girdisi, içinde "market" veya "alışveriş" geçen bir görevle ilgilidir. "toplantıyı 3'e al" girdisi, mevcut bir toplantı görevinin zamanını günceller.
    *   Eğer girdi mevcut bir görevi güncelliyor veya ona ekleme yapıyorsa, o görevi GÜNCELLE.
    *   Eğer girdi tamamen yeni ve bağımsız bir görevse, YENİ bir görev oluştur.

2.  **Çıktı Formatı (En Önemli Kural):**
    *   Çıktın HER ZAMAN şu formatta bir JSON nesnesi olmalı: '{"newTasks": [...], "updatedTasks": [...] }'.
    *   \`newTasks\` dizisi: Tamamen yeni oluşturulmuş görevleri içerir. Bu görevlerin 'id'si OLMAYACAK. Her görev objesi 'task', 'dueDate' (ISO 8601 veya null), ve 'location' (string veya null) alanlarını içermelidir.
    *   \`updatedTasks\` dizisi: Mevcut görevlerden güncellenmiş olanları içerir. Her görev objesi, güncellenen görevin ORİJİNAL 'id'sini MUTLAKA içermelidir. Ayrıca sadece DEĞİŞEN alanları içermelidir (örn: \`{"id": "123", "task": "Domates, biber ve patates al"}\`). Eğer bir görevin tüm metni değişiyorsa, tüm metni gönder.
    *   Eğer hiçbir görev oluşturulmadı veya güncellenmediyse, boş diziler döndür: \`{"newTasks": [], "updatedTasks": []}\`.
    *   Başka hiçbir metin veya açıklama ekleme.

3.  **Tarih ve Saat Yorumlama:** Metindeki TÜM zaman ifadelerini ("yarın saat 10'da", "akşam 5'te") algıla ve MUTLAKA tam ve doğru bir ISO 8601 formatına (YYYY-MM-DDTHH:mm:ss.sssZ) çevir. Eğer yıl belirtilmemişse, mevcut yılı kullan; tarih geçmişte kalıyorsa bir sonraki yılı kullan. Asla alakasız bir gelecek yılı (örn: 2026) uydurma.

4.  **Konum Bilgisini Çıkar ve Zenginleştir:** Metindeki belirgin mekan, adres veya şirket isimlerini algıla ve \`location\` alanına yaz. Konum yoksa, \`location\` değerini \`null\` yap. **Eğer kullanıcı 'yakındaki market' gibi göreceli bir konum belirtirse ve kullanıcının mevcut konumu belliyse, bu bilgiyi kullanarak görevin konumunu daha spesifik ve anlamlı hale getirmeye çalış (örn: 'Zeytinburnu civarındaki market').**

Örnek 1 (Yeni Görev):
Mevcut Görevler: []
Kullanıcı Girdisi: "yarın sabah 9'da XYZ Tekstil'e git"
Çıktı: {"newTasks": [{"task": "XYZ Tekstil'e gitmek", "dueDate": "${new Date(new Date().setDate(new Date().getDate() + 1)).toISOString().split('T')[0]}T06:00:00.000Z", "location": "XYZ Tekstil"}], "updatedTasks": []}

Örnek 2 (Görev Güncelleme/Birleştirme):
Mevcut Görevler: [{"id": "abc-123", "text": "Akşam markete uğrayıp domates ve biber al", "locationName": "Market"}]
Kullanıcı Girdisi: "patates de alınacak"
Çıktı: {"newTasks": [], "updatedTasks": [{"id": "abc-123", "task": "Akşam markete uğrayıp domates, biber ve patates al"}]}
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Kullanıcı Girdisi:\n---\n${text}\n---`,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
            },
        });

        const jsonString = response.text.trim();
        const parsed = JSON.parse(jsonString);

        if (parsed && Array.isArray(parsed.newTasks) && Array.isArray(parsed.updatedTasks)) {
            return parsed as GeminiResponse;
        }

        throw new Error("Invalid format from API. Expected { newTasks: [...], updatedTasks: [...] }");

    } catch (error) {
        console.error("Error parsing tasks with Gemini:", error);
        // Fallback to simple line-by-line parsing on error
        return { 
            newTasks: text.split('\n').map(line => ({
                task: line.trim(),
                dueDate: null,
                location: null
            })).filter(item => item.task.length > 0),
            updatedTasks: []
        };
    }
};

