interface SettingsScreenProps {
    settings: Settings;
    setSettings: React.Dispatch<React.SetStateAction<Settings>>;
    patterns: Pattern[];
    setPatterns: React.Dispatch<React.SetStateAction<Pattern[]>>;
    customers: Customer[];
    setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
    tasks: Task[];
    setTasks: React.Dispatch<React.SetStateAction<Task[]>>;
    employees: Employee[];
    setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
}

const SettingsScreen: React.FC<SettingsScreenProps> = ({ 
    settings, setSettings, 
    patterns, setPatterns, 
    customers, setCustomers,
    tasks, setTasks,
    employees, setEmployees
}) => {
    const [formState, setFormState] = useState<FormState>({
        electricityCostKwh: String(settings.electricityCostKwh),
        machinePowerWatt: String(settings.machinePowerWatt),
        rhinestones: settings.rhinestones || [],
        companyName: settings.companyName || '',
        companyAddress: settings.companyAddress || '',
        companyPhoneNumbers: settings.companyPhoneNumbers || [''],
        companyEmail: settings.companyEmail || '',
        companyTaxNumber: settings.companyTaxNumber || '',
        companyLogo: settings.companyLogo || '',
        minutesPer100Meters: String(settings.minutesPer100Meters || 20),
        notificationLeadTimeHours: String(settings.notificationLeadTimeHours || 24),
        requirePasswordForDelete: settings.requirePasswordForDelete,
        confirmationPassword: settings.confirmationPassword || '',
    });

    const [toastInfo, setToastInfo] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
    const [activeTab, setActiveTab] = useState<ActiveTab>('company');
    const [isRestoreModalOpen, setIsRestoreModalOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const isInitialMount = useRef(true);

    // Auto-save settings on form change with debounce
    useEffect(() => {
        if (isInitialMount.current) {
            isInitialMount.current = false;
            return;
        }

        const handler = setTimeout(() => {
            const newSettings: Settings = {
                electricityCostKwh: parseFloat(formState.electricityCostKwh) || 0,
                machinePowerWatt: parseFloat(formState.machinePowerWatt) || 0,
                rhinestones: formState.rhinestones,
                companyName: formState.companyName.trim(),
                companyAddress: formState.companyAddress.trim(),
                companyPhoneNumbers: formState.companyPhoneNumbers.map(p => p.trim()).filter(p => p),
                companyEmail: formState.companyEmail.trim(),
                companyTaxNumber: formState.companyTaxNumber.trim(),
                companyLogo: formState.companyLogo || undefined,
                minutesPer100Meters: parseInt(formState.minutesPer100Meters, 10) || 20,
                notificationLeadTimeHours: parseInt(formState.notificationLeadTimeHours, 10) || 24,
                requirePasswordForDelete: formState.requirePasswordForDelete,
                confirmationPassword: formState.confirmationPassword.trim(),
            };

            setSettings(newSettings);
            setToastInfo({ message: "Değişiklikler otomatik kaydedildi.", type: 'success' });

        }, 1500); // Debounce time: 1.5 seconds

        return () => {
            clearTimeout(handler);
        };
    }, [formState, setSettings]);

    // State for new rhinestone form
    const [newRhinestoneName, setNewRhinestoneName] = useState('');
    const [newRhinestoneCost, setNewRhinestoneCost] = useState('');
    const [newRhinestoneWeight, setNewRhinestoneWeight] = useState('');
    const [newRhinestoneImage, setNewRhinestoneImage] = useState<string | null>(null);

    const handleNumericChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        if (/^\d*\.?\d*$/.test(value)) {
            setFormState(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleIntegerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        if (/^\d*$/.test(value)) {
            setFormState(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (index: number, value: string) => {
        const newPhones = [...formState.companyPhoneNumbers];
        newPhones[index] = value;
        setFormState(prev => ({ ...prev, companyPhoneNumbers: newPhones }));
    };

    const addPhone = () => {
        setFormState(prev => ({ ...prev, companyPhoneNumbers: [...prev.companyPhoneNumbers, ''] }));
    };

    const removePhone = (index: number) => {
        if (formState.companyPhoneNumbers.length <= 1) return;
        const newPhones = formState.companyPhoneNumbers.filter((_, i) => i !== index);
        setFormState(prev => ({ ...prev, companyPhoneNumbers: newPhones }));
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                const base64 = await compressAndEncodeImage(e.target.files[0]);
                setFormState(prev => ({...prev, companyLogo: base64}));
            } catch (error) {
                console.error("Error compressing and encoding image:", error);
                setToastInfo({ message: "Logo yüklenirken hata oluştu.", type: 'error' });
            }
        }
    };

    const handleRhinestoneImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                const base64 = await compressAndEncodeImage(e.target.files[0], 100);
                setNewRhinestoneImage(base64);
            } catch (error) {
                console.error("Error compressing rhinestone image:", error);
                setToastInfo({ message: "Taş resmi yüklenirken hata oluştu.", type: 'error' });
            }
        }
    };

    const handleAddRhinestone = () => {
        const cost = parseFloat(newRhinestoneCost);
        const weight = parseFloat(newRhinestoneWeight);
        if (newRhinestoneName.trim() && !isNaN(cost) && cost > 0 && !isNaN(weight) && weight > 0) {
            const newRhinestone: Rhinestone = {
                id: Date.now().toString(),
                name: newRhinestoneName.trim(),
                costPerGross: cost,
                weightGramsPerGross: weight,
                image: newRhinestoneImage || undefined,
            };
            setFormState(prev => ({ ...prev, rhinestones: [...prev.rhinestones, newRhinestone]}));
            setNewRhinestoneName('');
            setNewRhinestoneCost('');
            setNewRhinestoneWeight('');
            setNewRhinestoneImage(null);
        } else {
            setToastInfo({ message: "Lütfen tüm taş bilgilerini geçerli şekilde girin.", type: 'error' });
        }
    };

    const handleRemoveRhinestone = (id: string) => {
        setFormState(prev => ({...prev, rhinestones: prev.rhinestones.filter(r => r.id !== id)}));
    };

    const handleDownloadAllData = () => {
        const allData = {
            customers,
            tasks,
            employees,
            patterns,
            settings,
            backupDetails: {
                version: '1.0.0',
                createdAt: new Date().toISOString(),
            }
        };

        try {
            const dataStr = JSON.stringify(allData, null, 2);
            const dataBlob = new Blob([dataStr], { type: "application/json" });
            const dataUrl = URL.createObjectURL(dataBlob);
            const linkElement = document.createElement('a');
            const date = new Date().toISOString().split('T')[0];
            linkElement.setAttribute('href', dataUrl);
            linkElement.setAttribute('download', `is-takip-yedek-${date}.json`);
            document.body.appendChild(linkElement);
            linkElement.click();
            document.body.removeChild(linkElement);
            URL.revokeObjectURL(dataUrl);
            setToastInfo({ message: "Tüm veriler başarıyla indirildi.", type: 'success' });
        } catch (error) {
            console.error("Error downloading all data:", error);
            setToastInfo({ message: "Veri indirilirken bir hata oluştu.", type: 'error' });
        }
    };

    const handleRestoreConfirm = () => {
        setIsRestoreModalOpen(false);
        fileInputRef.current?.click();
    };

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) {
            return;
        }

        if (file.type !== 'application/json') {
            setToastInfo({ message: 'Geçersiz dosya türü. Lütfen .json yedek dosyasını seçin.', type: 'error' });
            return;
        }

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result;
                if (typeof text !== 'string') {
                    throw new Error("Dosya okunamadı.");
                }
                const data = JSON.parse(text);

                // Basic validation to ensure it's our backup file
                if (data && data.customers && data.tasks && data.employees && data.patterns && data.settings) {
                    setCustomers(data.customers);
                    setTasks(data.tasks);
                    setEmployees(data.employees);
                    setPatterns(data.patterns);
                    setSettings(data.settings);
                    setToastInfo({ message: 'Veriler başarıyla geri yüklendi.', type: 'success' });
                } else {
                    throw new Error("Yedek dosyası geçersiz veya bozuk.");
                }
            } catch (error) {
                console.error("Error restoring data:", error);
                setToastInfo({ message: `Geri yükleme başarısız: ${(error as Error).message}`, type: 'error' });
            }
        };
        reader.readAsText(file);
        // Reset file input so the same file can be selected again
        event.target.value = ''; 
    };

    const renderContent = () => {
        switch (activeTab) {
            case 'company':
                return (
                    <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Firma Bilgileri</h3>
                        <div>
                            <label className="block text-sm font-medium text-gray-300">Firma Logosu</label>
                            <div className="mt-2 flex items-center gap-4">
                                {formState.companyLogo ? (
                                    <img src={formState.companyLogo} alt="Firma Logosu" className="h-16 w-16 object-contain bg-white p-1 rounded-md" />
                                ) : (
                                    <div className="h-16 w-16 bg-gray-700 rounded-md flex items-center justify-center text-gray-500 text-xs text-center">Logo Yok</div>
                                )}
                                <div className="flex flex-col gap-2">
                                    <label className="cursor-pointer px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500 transition-colors">
                                        Logo Yükle
                                        <input type="file" accept="image/png, image/jpeg" className="hidden" onChange={handleLogoUpload} />
                                    </label>
                                    {formState.companyLogo && (
                                        <button type="button" onClick={() => setFormState(p => ({...p, companyLogo: ''}))} className="px-3 py-1 bg-red-600 text-white text-sm font-semibold rounded-lg hover:bg-red-500 transition-colors">
                                            Logoyu Kaldır
                                        </button>
                                    )}
                                </div>
                            </div>
                        </div>
                        <InputField name="companyName" label="Firma Adı" value={formState.companyName} onChange={handleTextChange} />
                        <TextareaField name="companyAddress" label="Firma Adresi" description="Faturada görünecek açık adresi girin." value={formState.companyAddress} onChange={handleTextChange} />
                        <div>
                            <label className="block text-sm font-medium text-gray-300 mb-2">Telefon Numaraları</label>
                            {formState.companyPhoneNumbers.map((phone, index) => (
                                <div key={index} className="flex items-center gap-2 mb-2">
                                    <input type="tel" value={phone} onChange={(e) => handlePhoneChange(index, e.target.value)} className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" placeholder="örn: +90 555 123 4567" />
                                    <button type="button" onClick={() => removePhone(index)} disabled={formState.companyPhoneNumbers.length <= 1} className="p-2 bg-red-600 text-white rounded-md hover:bg-red-500 disabled:opacity-50 disabled:cursor-not-allowed">
                                        <TrashIcon className="h-4 w-4" />
                                    </button>
                                </div>
                            ))}
                            <button type="button" onClick={addPhone} className="flex items-center gap-2 text-sm px-3 py-1 bg-blue-600 text-white rounded-md hover:bg-blue-500">
                                <PlusIcon /> Yeni Telefon Ekle
                            </button>
                        </div>
                        <InputField name="companyEmail" label="E-posta Adresi" value={formState.companyEmail} onChange={handleTextChange} type="email" inputMode="email" />
                        <InputField name="companyTaxNumber" label="Vergi Numarası" value={formState.companyTaxNumber} onChange={handleTextChange} />
                    </div>
                );
            case 'costs':
                return (
                     <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Genel Maliyetler</h3>
                        <InputField name="electricityCostKwh" label="Elektrik Maliyeti (kWh başına)" description="1 kWh birim fiyatını girin." value={formState.electricityCostKwh} onChange={handleNumericChange} type="text" inputMode="decimal" />
                        <InputField name="machinePowerWatt" label="Makine Gücü (Watt)" description="Makinenin saatte harcadığı ortalama gücü girin." value={formState.machinePowerWatt} onChange={handleIntegerChange} type="text" inputMode="decimal" />
                    </div>
                );
            case 'rhinestones':
                return (
                    <div className="space-y-6">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Taş Yönetimi</h3>
                        <div className="p-3 bg-gray-700/50 rounded-lg space-y-3">
                            <h4 className="text-md font-semibold text-gray-300">Yeni Taş Ekle</h4>
                            <input type="text" value={newRhinestoneName} onChange={e => setNewRhinestoneName(e.target.value)} placeholder="Taş Adı (örn: SS10 Kristal)" className="w-full bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                            <div className="flex gap-2">
                                <input type="number" step="0.01" value={newRhinestoneCost} onChange={e => setNewRhinestoneCost(e.target.value)} placeholder="Gross Maliyeti" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                                <input type="number" step="0.01" value={newRhinestoneWeight} onChange={e => setNewRhinestoneWeight(e.target.value)} placeholder="Gross Ağırlığı (gram)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-gray-400 mb-1">Taş Resmi (İsteğe Bağlı)</label>
                                <input type="file" accept="image/*" onChange={handleRhinestoneImageUpload} className="w-full text-sm text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-teal-600 file:text-white hover:file:bg-teal-500" />
                                {newRhinestoneImage && <img src={newRhinestoneImage} alt="Önizleme" className="mt-2 h-10 w-10 rounded-full object-cover" />}
                            </div>
                            <button type="button" onClick={handleAddRhinestone} className="w-full px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-500">Ekle</button>
                        </div>
                        <div>
                            <h4 className="text-md font-semibold text-gray-300 mb-2">Kayıtlı Taşlar</h4>
                            <ul className="space-y-2">
                                {formState.rhinestones.map(r => (
                                    <li key={r.id} className="flex justify-between items-center bg-gray-700 p-2 rounded-md">
                                        <div className="flex items-center gap-3">
                                            <img src={r.image || 'https://via.placeholder.com/40/4B5563/FFFFFF?text=?'} alt={r.name} className="h-10 w-10 rounded-full object-cover bg-gray-600" />
                                            <div>
                                                <p className="font-semibold text-gray-200">{r.name}</p>
                                                <p className="text-xs text-gray-400">{r.costPerGross} / Gross, {r.weightGramsPerGross} gr/Gross</p>
                                            </div>
                                        </div>
                                        <button type="button" onClick={() => handleRemoveRhinestone(r.id)} className="p-1 text-red-500 hover:text-red-400"><TrashIcon className="h-4 w-4"/></button>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    </div>
                );
             case 'patterns':
                return (
                    <PatternManagementScreen patterns={patterns} setPatterns={setPatterns} settings={settings} />
                );
            case 'calculations':
                return (
                    <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Hesaplama Ayarları</h3>
                        <InputField name="minutesPer100Meters" label="100 Metre Başına Süre (Dakika)" description="İşlerin tahmini süresini hesaplamak için kullanılır." value={formState.minutesPer100Meters} onChange={handleIntegerChange} type="text" inputMode="decimal" />
                    </div>
                );
            case 'assistant':
                 return (
                    <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Asistan Ayarları</h3>
                        <InputField name="notificationLeadTimeHours" label="Bildirim Öncesi Süre (Saat)" description="Asistan, görevleri bu süre kadar önceden size hatırlatacaktır." value={formState.notificationLeadTimeHours} onChange={handleIntegerChange} type="text" inputMode="decimal" />
                    </div>
                );
            case 'security':
                return (
                    <div className="space-y-4">
