                                {newRhinestoneImage && <img src={newRhinestoneImage} alt="Önizleme" className="mt-2 h-10 w-10 rounded-full object-cover" />}
                            </div>
                            <button type="button" onClick={handleAddRhinestone} className="w-full px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-500">Ekle</button>
                        </div>
                        <div>
                            <h4 className="text-md font-semibold text-gray-300 mb-2">Kayıtlı Taşlar</h4>
                            <ul className="space-y-2">
                                {formState.rhinestones.map(r => (
                                    <li key={r.id} className="flex justify-between items-center bg-gray-700 p-2 rounded-md">
                                        <div className="flex items-center gap-3">
                                            <img src={r.image || 'https://via.placeholder.com/40/4B5563/FFFFFF?text=?'} alt={r.name} className="h-10 w-10 rounded-full object-cover bg-gray-600" />
                                            <div>
                                                <p className="font-semibold text-gray-200">{r.name}</p>
                                                <p className="text-xs text-gray-400">{r.costPerGross} / Gross, {r.weightGramsPerGross} gr/Gross</p>
