            case 'data':
                return (
                    <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Veri Yönetimi</h3>
                        <div className="p-4 bg-gray-700/50 rounded-lg">
