import React, { useState, useEffect, useRef } from 'react';
import type { Customer, Task, View, Pattern, Settings, Rhinestone, Employee } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';
import CustomerListScreen from './components/CustomerListScreen';
import TaskListScreen from './components/TaskListScreen';
import PatternManagementScreen from './components/PatternManagementScreen';
import HomeScreen from './components/HomeScreen';
import SplashScreen from './components/SplashScreen';
import { CustomersIcon, TasksIcon, PatternIcon, HomeIcon, SettingsIcon, MoneyIcon } from './components/Icons';
import { calculateTravelTime } from './services/locationService';
import CustomerDetailScreen from './components/CustomerDetailScreen';
import SettingsScreen from './components/SettingsScreen';
import EmployeeAdvanceScreen from './components/EmployeeAdvanceScreen';

const defaultPatterns: Pattern[] = [
    { id: '1', name: 'Düz Baskı', pricePerMeter: 15, rhinestonesPerMeter: 0.5, image: 'https://via.placeholder.com/150/10B981/FFFFFF?text=Düz' },
    { id: '2', name: 'Desenli A', pricePerMeter: 25, rhinestonesPerMeter: 1.5, image: 'https://via.placeholder.com/150/3B82F6/FFFFFF?text=Desenli+A' },
    { id: '3', name: 'Desenli B (Simli)', pricePerMeter: 35, rhinestonesPerMeter: 2.0, image: 'https://via.placeholder.com/150/F59E0B/FFFFFF?text=Simli' },
    { id: '4', name: 'Özel Tasarım', pricePerMeter: 50, rhinestonesPerMeter: 3.0, image: 'https://via.placeholder.com/150/8B5CF6/FFFFFF?text=Özel' },
];

const defaultRhinestones: Rhinestone[] = [
    { id: '1', name: 'SS10 Kristal', costPerGross: 50, weightGramsPerGross: 30 },
    { id: '2', name: 'SS16 AB', costPerGross: 75, weightGramsPerGross: 60 },
];

const defaultSettings: Settings = {
    electricityCostKwh: 3.5,
    machinePowerWatt: 2000,
    rhinestones: defaultRhinestones,
    companyName: 'AB AYÇAM Tekstil',
    companyAddress: 'Örnek Mah. Sanayi Cad. No:123\n34000, Sanayi Bölgesi / İstanbul',
    companyPhoneNumbers: ['+90 (212) 555 00 00'],
    companyEmail: 'info@abaycam.com',
    companyTaxNumber: '1234567890',
    companyLogo: undefined,
    minutesPer100Meters: 20,
    notificationLeadTimeHours: 24,
    requirePasswordForDelete: true,
    confirmationPassword: '1234',
};


const App: React.FC = () => {
  const [customers, setCustomers] = useLocalStorage<Customer[]>('customers', []);
  const [tasks, setTasks] = useLocalStorage<Task[]>('tasks', []);
  const [patterns, setPatterns] = useLocalStorage<Pattern[]>('patterns', defaultPatterns);
  const [settings, setSettings] = useLocalStorage<Settings>('settings', defaultSettings);
  const [employees, setEmployees] = useLocalStorage<Employee[]>('employees', []);
  const [currentView, setCurrentView] = useState<View>('home');
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);
  const notifiedTaskIds = useRef(new Set<string>());
  const [isLoading, setIsLoading] = useState(true);

  // Splash screen timer
  useEffect(() => {
    const timer = setTimeout(() => {
        setIsLoading(false);
    }, 2000); // 2 seconds

    return () => clearTimeout(timer); // Cleanup timer on unmount
  }, []);

  // One-time migration for settings structure changes
  useEffect(() => {
    setSettings(prevSettings => {
        let needsUpdate = false;
        const newSettings = { ...prevSettings };

        // Migration from single rhinestone values to array
        if (!prevSettings.hasOwnProperty('rhinestones') && prevSettings.hasOwnProperty('rhinestoneCostPerGross')) {
            newSettings.rhinestones = [{
                id: '1',
                name: 'Varsayılan Taş',
                costPerGross: (prevSettings as any).rhinestoneCostPerGross,
                weightGramsPerGross: (prevSettings as any).rhinestoneWeightGramsPerGross
            }];
            delete (newSettings as any).rhinestoneCostPerGross;
            delete (newSettings as any).rhinestoneWeightGramsPerGross;
            needsUpdate = true;
        }

        // Add notificationLeadTimeHours if it doesn't exist
        if (!prevSettings.hasOwnProperty('notificationLeadTimeHours')) {
            newSettings.notificationLeadTimeHours = defaultSettings.notificationLeadTimeHours;
            needsUpdate = true;
        }

        return needsUpdate ? newSettings : prevSettings;
    });
  }, []);

  // Scroll input into view on focus for better mobile keyboard experience
  useEffect(() => {
    const handleFocus = (event: FocusEvent) => {
        const target = event.target as HTMLElement;
        if (
            target.tagName === 'INPUT' ||
            target.tagName === 'TEXTAREA' ||
            target.isContentEditable
        ) {
            setTimeout(() => {
                target.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 300);
        }
    };

    document.addEventListener('focusin', handleFocus);
    return () => {
        document.removeEventListener('focusin', handleFocus);
    };
}, []);


  // Fetch user location once on component mount
  useEffect(() => {
    navigator.geolocation.getCurrentPosition(
      (position) => {
        setUserLocation({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
        });
      },
      (error) => {
        console.error("Error getting user location:", error);
      }
    );
  }, []);

  // Proactive notification logic
  useEffect(() => {
    const interval = setInterval(() => {
      const incompleteTasks = tasks.filter(t => !t.completed && t.dueDate && t.locationCoords && !notifiedTaskIds.current.has(t.id));

      if (incompleteTasks.length > 0 && userLocation) {
         incompleteTasks.forEach(task => {
           const dueDate = new Date(task.dueDate!);
           const now = new Date();

           if(dueDate > now) {
                const travelTimeMinutes = calculateTravelTime(userLocation, task.locationCoords!);
                const PREPARATION_BUFFER_MINUTES = settings.notificationLeadTimeHours * 60;
                const totalLeadTime = (travelTimeMinutes + PREPARATION_BUFFER_MINUTES) * 60 * 1000; // in milliseconds

                const departureTime = new Date(dueDate.getTime() - totalLeadTime);

                if (now >= departureTime) {
                    alert(`HATIRLATMA: "${task.text}" göreviniz için yola çıkma zamanı yaklaşıyor.`);
                    notifiedTaskIds.current.add(task.id);
                }
           }
         });
      }
    }, 60 * 1000); // Check every minute

    return () => clearInterval(interval);
  }, [tasks, userLocation, settings.notificationLeadTimeHours]);

  const handleSelectCustomer = (customerId: string) => {
    setSelectedCustomerId(customerId);
    setCurrentView('customerDetail');
  };

  const handleBackToList = () => {
    setSelectedCustomerId(null);
    setCurrentView('customers');
  };

  const renderContent = () => {
    switch (currentView) {
      case 'home':
        return <HomeScreen customers={customers} tasks={tasks} onNavigate={setCurrentView} />;
      case 'assistant':
        return <TaskListScreen tasks={tasks} setTasks={setTasks} userLocation={userLocation} />;
      case 'customers':
        return (
          <CustomerListScreen
            customers={customers}
            setCustomers={setCustomers}
            onSelectCustomer={handleSelectCustomer}
          />
        );
      case 'customerDetail':
        const selectedCustomer = customers.find(c => c.id === selectedCustomerId);
        if (selectedCustomer) {
          return (
              <CustomerDetailScreen
                customer={selectedCustomer}
                setCustomers={setCustomers}
                onBack={handleBackToList}
                patterns={patterns}
                settings={settings}
              />
          );
        }
        // Fallback if customer not found
        handleBackToList();
        return null;
      case 'advances':
          return <EmployeeAdvanceScreen employees={employees} setEmployees={setEmployees} settings={settings} />;
      case 'settings':
        return <SettingsScreen 
            settings={settings} 
            setSettings={setSettings} 
            patterns={patterns} 
            setPatterns={setPatterns} 
            customers={customers}
            tasks={tasks}
            employees={employees}
            setCustomers={setCustomers}
            setTasks={setTasks}
            setEmployees={setEmployees}
             />;
      default:
        return <HomeScreen customers={customers} tasks={tasks} onNavigate={setCurrentView} />;
    }
  };

  // FIX: Changed icon type from JSX.Element to React.ReactElement to resolve "Cannot find namespace 'JSX'" error.
  const NavButton = ({ view, label, icon }: { view: View, label: string, icon: React.ReactElement }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full pt-2 pb-1 transition-colors duration-200 ${currentView === view || (view === 'customers' && currentView === 'customerDetail') ? 'text-teal-400' : 'text-gray-400 hover:text-teal-300'}`}
    >
      {icon}
      <span className="text-xs mt-1">{label}</span>
    </button>
  );

  return (
    <>
      {isLoading ? (
        <SplashScreen />
      ) : (
        <div className="flex flex-col h-screen font-sans">
          <header className="bg-gray-800 shadow-md p-4 text-center">
            <h1 className="text-2xl font-bold text-teal-400">İş Takip Asistanı</h1>
          </header>
          <main className="flex-grow overflow-y-auto p-4 pb-20 bg-gray-900">
            {renderContent()}
          </main>
          <nav className="fixed bottom-0 left-0 right-0 bg-gray-800 border-t border-gray-700 shadow-lg flex justify-around">
            <NavButton view="home" label="Ana Sayfa" icon={<HomeIcon />} />
            <NavButton view="assistant" label="Asistan" icon={<TasksIcon />} />
            <NavButton view="customers" label="Müşteriler" icon={<CustomersIcon />} />
            <NavButton view="advances" label="Avans" icon={<MoneyIcon />} />
            <NavButton view="settings" label="Ayarlar" icon={<SettingsIcon />} />
          </nav>
        </div>
      )}
    </>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import type { Employee, Advance, Settings } from '../types';
import { PlusIcon, ChevronDownIcon, TrashIcon } from './Icons';
import ConfirmationModal from './ConfirmationModal';

interface EmployeeAdvanceScreenProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  settings: Settings;
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', {
        style: 'decimal',
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(amount);
};

const formatDate = (isoString: string) => {
    if (!isoString) return '';
    const date = new Date(isoString);
    return date.toLocaleDateString('tr-TR', {
        day: '2-digit',
        month: 'long',
        year: 'numeric'
    });
};

const EmployeeAdvanceScreen: React.FC<EmployeeAdvanceScreenProps> = ({ employees, setEmployees, settings }) => {
    const [newEmployeeName, setNewEmployeeName] = useState('');
    const [expandedEmployeeId, setExpandedEmployeeId] = useState<string | null>(null);
    const [advanceToDelete, setAdvanceToDelete] = useState<{ employeeId: string; advanceId: string } | null>(null);

    // Form state for adding an advance
    const [advanceAmount, setAdvanceAmount] = useState('');
    const [advanceDescription, setAdvanceDescription] = useState('');

    const handleAddEmployee = (e: React.FormEvent) => {
        e.preventDefault();
        if (newEmployeeName.trim() === '') return;

        const newEmployee: Employee = {
            id: Date.now().toString(),
            name: newEmployeeName.trim(),
            advances: [],
        };
        setEmployees(prev => [newEmployee, ...prev].sort((a,b) => a.name.localeCompare(b.name)));
        setNewEmployeeName('');
    };

    const handleToggleEmployee = (employeeId: string) => {
        if (expandedEmployeeId === employeeId) {
            setExpandedEmployeeId(null);
        } else {
            setExpandedEmployeeId(employeeId);
            // Reset form when opening a new one
            setAdvanceAmount('');
            setAdvanceDescription('');
        }
    };

    const handleAddAdvance = (employeeId: string) => {
        const amount = parseFloat(advanceAmount);
        if (isNaN(amount) || amount <= 0) {
            alert("Lütfen geçerli bir avans tutarı girin.");
            return;
        }

        const newAdvance: Advance = {
            id: Date.now().toString(),
            amount: amount,
            date: new Date().toISOString(),
            description: advanceDescription.trim() || undefined,
        };

        setEmployees(prev => prev.map(emp => {
            if (emp.id === employeeId) {
                return { ...emp, advances: [newAdvance, ...emp.advances] };
            }
            return emp;
        }));

        // Reset form
        setAdvanceAmount('');
        setAdvanceDescription('');
    };

    const handleDeleteAdvanceRequest = (employeeId: string, advanceId: string) => {
        setAdvanceToDelete({ employeeId, advanceId });
    };

    const handleConfirmDelete = () => {
        if (!advanceToDelete) return;
        const { employeeId, advanceId } = advanceToDelete;

        setEmployees(prev => prev.map(emp => {
            if (emp.id === employeeId) {
                return {
                    ...emp,
                    advances: emp.advances.filter(adv => adv.id !== advanceId)
                };
            }
            return emp;
        }));

        setAdvanceToDelete(null);
    };

    const sortedEmployees = useMemo(() => {
        return [...employees].sort((a, b) => a.name.localeCompare(b.name));
    }, [employees]);

    return (
        <div>
            <h2 className="text-2xl font-bold text-teal-400 mb-6">Personel Avans Takibi</h2>

            <form onSubmit={handleAddEmployee} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 flex gap-3">
                <input
                    type="text"
                    value={newEmployeeName}
                    onChange={(e) => setNewEmployeeName(e.target.value)}
                    placeholder="Yeni Personel Adı"
                    className="flex-grow bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
                />
                <button type="submit" className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 transition-colors disabled:opacity-50" disabled={!newEmployeeName.trim()}>
                    <PlusIcon /> Ekle
                </button>
            </form>

            {employees.length === 0 ? (
                <p className="text-gray-500 text-center py-4">Henüz personel eklenmemiş.</p>
            ) : (
                <ul className="space-y-3">
                    {sortedEmployees.map(employee => {
                        const totalAdvance = employee.advances.reduce((sum, adv) => sum + adv.amount, 0);
                        const isExpanded = expandedEmployeeId === employee.id;

                        return (
                            <li key={employee.id} className="bg-gray-800 rounded-lg shadow-md transition-all">
                                <div className="p-4 flex justify-between items-center cursor-pointer" onClick={() => handleToggleEmployee(employee.id)}>
                                    <h3 className="font-bold text-lg text-gray-200">{employee.name}</h3>
                                    <div className="flex items-center gap-4">
                                        <div className="text-right">
                                            <p className="text-sm text-gray-400">Toplam Avans</p>
                                            <p className="font-semibold text-xl text-red-400">{formatCurrency(totalAdvance)}</p>
                                        </div>
                                        <ChevronDownIcon className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} />
                                    </div>
                                </div>

                                {isExpanded && (
                                    <div className="p-4 border-t border-gray-700 space-y-4">
                                        {/* Add Advance Form */}
                                        <div className="p-3 bg-gray-700/50 rounded-lg space-y-3">
                                            <h4 className="text-md font-semibold text-gray-300">Yeni Avans Ekle</h4>
                                            <div className="flex flex-col sm:flex-row gap-2">
                                                <input
                                                    type="number"
                                                    step="0.01"
                                                    value={advanceAmount}
                                                    onChange={e => setAdvanceAmount(e.target.value)}
                                                    placeholder="Tutar"
                                                    className="w-full sm:w-1/3 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                                />
                                                <input
                                                    type="text"
                                                    value={advanceDescription}
                                                    onChange={e => setAdvanceDescription(e.target.value)}
                                                    placeholder="Açıklama (isteğe bağlı)"
                                                    className="flex-grow bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                                />
                                            </div>
                                            <button 
                                                type="button" 
                                                onClick={() => handleAddAdvance(employee.id)} 
                                                disabled={!advanceAmount}
                                                className="w-full px-3 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-500 disabled:opacity-50"
                                            >
                                                Avansı Kaydet
                                            </button>
                                        </div>

                                        {/* Advance History */}
                                        <div>
                                            <h4 className="text-md font-semibold text-gray-300 mb-2">Avans Geçmişi</h4>
                                            {employee.advances.length > 0 ? (
                                                <ul className="divide-y divide-gray-700/50 max-h-60 overflow-y-auto">
                                                    {employee.advances.map(advance => (
                                                        <li key={advance.id} className="py-2">
                                                            <div className="flex justify-between items-start">
                                                                <div>
                                                                    <p className="font-semibold text-gray-200">{formatCurrency(advance.amount)}</p>
                                                                    {advance.description && <p className="text-xs text-gray-400 mt-1">{advance.description}</p>}
                                                                </div>
                                                                <div className="flex items-center gap-3">
                                                                    <p className="text-xs text-gray-500">{formatDate(advance.date)}</p>
                                                                    <button 
                                                                        onClick={() => handleDeleteAdvanceRequest(employee.id, advance.id)}
