                                className="absolute top-1 right-1 z-10 p-1 bg-red-600/80 hover:bg-red-500 rounded-full text-white"
                                aria-label="Fotoğrafı Sil"
                            >
                                <TrashIcon className="h-4 w-4" />
                            </button>
                            <button
                                onClick={() => onImageClick(photo)}
