import { useEffect, useState } from 'react';
import { Settings } from './types';
import { getSettings, saveSettings } from './storage';
import { useLocation } from './LocationContext';
import { useTasks } from './TasksContext';
import { checkAndScheduleNotifications } from './notifications'; // Assuming this function exists

const defaultSettings: Settings = {
    // Other default settings...
    notificationLeadTimeMinutes: 1440, // 24 hours in minutes
    // More default settings...
};

function App() {
    const [settings, setSettings] = useState<Settings>(defaultSettings);
    const { userLocation } = useLocation();
    const { tasks } = useTasks();

    // Load settings from storage on component mount
    useEffect(() => {
        const loadSettings = async () => {
            const storedSettings = await getSettings();
            setSettings(storedSettings || defaultSettings);
        };
        loadSettings();
    }, []);

    // One-time migration for settings structure changes
    useEffect(() => {
        setSettings(prevSettings => {
            let needsUpdate = false;
            const newSettings = { ...prevSettings };

            // Migration for notification lead time from hours to minutes
            if (prevSettings.hasOwnProperty('notificationLeadTimeHours')) {
                newSettings.notificationLeadTimeMinutes = (prevSettings as any).notificationLeadTimeHours * 60;
                delete (newSettings as any).notificationLeadTimeHours;
                needsUpdate = true;
            } else if (!prevSettings.hasOwnProperty('notificationLeadTimeMinutes')) {
                // Add notificationLeadTimeMinutes if it doesn't exist at all
                newSettings.notificationLeadTimeMinutes = defaultSettings.notificationLeadTimeMinutes;
                needsUpdate = true;
            }

            return needsUpdate ? newSettings : prevSettings;
        });
    }, []);

    // Effect to check and schedule notifications
    useEffect(() => {
        const PREPARATION_BUFFER_MINUTES = settings.notificationLeadTimeMinutes;
        checkAndScheduleNotifications(tasks, userLocation, PREPARATION_BUFFER_MINUTES);
    }, [tasks, userLocation, settings.notificationLeadTimeMinutes]);

    // Save settings to storage whenever they change
    useEffect(() => {
        saveSettings(settings);
    }, [settings]);

    return (
        // ... Your app content ...
    );
}

export default App;
