const SettingsScreen: React.FC<SettingsScreenProps> = ({ 
    settings, setSettings, 
    patterns, setPatterns, 
    customers, setCustomers,
    tasks, setTasks,
    employees, setEmployees
}) => {
    const [formState, setFormState] = useState<FormState>({
        electricityCostKwh: String(settings.electricityCostKwh),
        machinePowerWatt: String(settings.machinePowerWatt),
        rhinestones: settings.rhinestones || [],
        companyName: settings.companyName || '',
        companyAddress: settings.companyAddress || '',
        companyPhoneNumbers: settings.companyPhoneNumbers || [''],
        companyEmail: settings.companyEmail || '',
        companyTaxNumber: settings.companyTaxNumber || '',
        companyLogo: settings.companyLogo || '',
        minutesPer100Meters: String(settings.minutesPer100Meters || 20),
        notificationLeadTimeMinutes: String(settings.notificationLeadTimeMinutes || 1440),
        requirePasswordForDelete: settings.requirePasswordForDelete,
        confirmationPassword: settings.confirmationPassword || '',
    });

    const [toastInfo, setToastInfo] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
    const [activeTab, setActiveTab] = useState<ActiveTab>('company');
    const [isRestoreModalOpen, setIsRestoreModalOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const isInitialMount = useRef(true);

    // Auto-save settings on form change with debounce
    useEffect(() => {
        if (isInitialMount.current) {
            isInitialMount.current = false;
            return;
        }

        const handler = setTimeout(() => {
            const newSettings: Settings = {
                electricityCostKwh: parseFloat(formState.electricityCostKwh) || 0,
                machinePowerWatt: parseFloat(formState.machinePowerWatt) || 0,
                rhinestones: formState.rhinestones,
                companyName: formState.companyName.trim(),
                companyAddress: formState.companyAddress.trim(),
                companyPhoneNumbers: formState.companyPhoneNumbers.map(p => p.trim()).filter(p => p),
                companyEmail: formState.companyEmail.trim(),
                companyTaxNumber: formState.companyTaxNumber.trim(),
                companyLogo: formState.companyLogo || undefined,
                minutesPer100Meters: parseInt(formState.minutesPer100Meters, 10) || 20,
                notificationLeadTimeMinutes: parseInt(formState.notificationLeadTimeMinutes, 10) || 1440,
                requirePasswordForDelete: formState.requirePasswordForDelete,
                confirmationPassword: formState.confirmationPassword.trim(),
            };

            setSettings(newSettings);

        }, 500); // Debounce time: 0.5 seconds

        return () => {
            clearTimeout(handler);
        };
    }, [formState, setSettings]);

    // State for new rhinestone form
    const [newRhinestoneName, setNewRhinestoneName] = useState('');
    const [newRhinestoneCost, setNewRhinestoneCost] = useState('');
    const [newRhinestoneWeight, setNewRhinestoneWeight] = useState('');
    const [newRhinestoneImage, setNewRhinestoneImage] = useState<string | null>(null);

    const handleNumericChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        if (/^\d*\.?\d*$/.test(value)) {
            setFormState(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleIntegerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        if (/^\d*$/.test(value)) {
            setFormState(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (index: number, value: string) => {
        const newPhones = [...formState.companyPhoneNumbers];
        newPhones[index] = value;
        setFormState(prev => ({ ...prev, companyPhoneNumbers: newPhones }));
    };

    const addPhone = () => {
        setFormState(prev => ({ ...prev, companyPhoneNumbers: [...prev.companyPhoneNumbers, ''] }));
    };

    const removePhone = (index: number) => {
        if (formState.companyPhoneNumbers.length <= 1) return;
        const newPhones = formState.companyPhoneNumbers.filter((_, i) => i !== index);
        setFormState(prev => ({ ...prev, companyPhoneNumbers: newPhones }));
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                const base64 = await compressAndEncodeImage(e.target.files[0]);
                setFormState(prev => ({...prev, companyLogo: base64}));
            } catch (error) {
                console.error("Error compressing and encoding image:", error);
                setToastInfo({ message: "Logo yüklenirken hata oluştu.", type: 'error' });
            }
        }
    };

    const handleRhinestoneImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                const base64 = await compressAndEncodeImage(e.target.files[0], 100);
                setNewRhinestoneImage(base64);
            } catch (error) {
                console.error("Error compressing rhinestone image:", error);
                setToastInfo({ message: "Taş resmi yüklenirken hata oluştu.", type: 'error' });
            }
        }
    };

    const handleAddRhinestone = () => {
        const cost = parseFloat(newRhinestoneCost);
        const weight = parseFloat(newRhinestoneWeight);
        if (newRhinestoneName.trim() && !isNaN(cost) && cost > 0 && !isNaN(weight) && weight > 0) {
            const newRhinestone: Rhinestone = {
                id: Date.now().toString(),
                name: newRhinestoneName.trim(),
                costPerGross: cost,
                weightGramsPerGross: weight,
                image: newRhinestoneImage || undefined,
            };
            setFormState(prev => ({ ...prev, rhinestones: [...prev.rhinestones, newRhinestone]}));
            setNewRhinestoneName('');
            setNewRhinestoneCost('');
            setNewRhinestoneWeight('');
            setNewRhinestoneImage(null);
        } else {
            setToastInfo({ message: "Lütfen tüm taş bilgilerini geçerli şekilde girin.", type: 'error' });
        }
    };

    const handleRemoveRhinestone = (id: string) => {
        setFormState(prev => ({...prev, rhinestones: prev.rhinestones.filter(r => r.id !== id)}));
    };

    const handleDownloadAllData = () => {
        const allData = {
            customers,
            tasks,
            employees,
            patterns,
            settings,
            backupDetails: {
                version: '1.0.0',
                createdAt: new Date().toISOString(),
            }
        };

        try {
            const dataStr = JSON.stringify(allData, null, 2);
            const dataBlob = new Blob([dataStr], { type: "application/json" });
            const dataUrl = URL.createObjectURL(dataBlob);
            const linkElement = document.createElement('a');
            const date = new Date().toISOString().split('T')[0];
            linkElement.setAttribute('href', dataUrl);
            linkElement.setAttribute('download', `is-takip-yedek-${date}.json`);
            document.body.appendChild(linkElement);
            linkElement.click();
            document.body.removeChild(linkElement);
            URL.revokeObjectURL(dataUrl);
            setToastInfo({ message: "Tüm veriler başarıyla indirildi.", type: 'success' });
        } catch (error) {
            console.error("Error downloading all data:", error);
            setToastInfo({ message: "Veri indirilirken bir hata oluştu.", type: 'error' });
        }
    };

    const handleRestoreConfirm = () => {
        setIsRestoreModalOpen(false);
        fileInputRef.current?.click();
    };

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) {
            return;
        }

        if (file.type !== 'application/json') {
            setToastInfo({ message: 'Geçersiz dosya türü. Lütfen .json yedek dosyasını seçin.', type: 'error' });
            return;
        }

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result;
                if (typeof text !== 'string') {
                    throw new Error("Dosya okunamadı.");
                }
                const data = JSON.parse(text);

                // Basic validation to ensure it's our backup file
                if (data && data.customers && data.tasks && data.employees && data.patterns && data.settings) {
                    setCustomers(data.customers);
                    setTasks(data.tasks);
                    setEmployees(data.employees);
                    setPatterns(data.patterns);
                    setSettings(data.settings);
                    setToastInfo({ message: 'Veriler başarıyla geri yüklendi.', type: 'success' });
                } else {
                    throw new Error("Yedek dosyası geçersiz veya bozuk.");
                }
            } catch (error) {
                console.error("Error restoring data:", error);
                setToastInfo({ message: `Geri yükleme başarısız: ${(error as Error).message}`, type: 'error' });
            }
        };
        reader.readAsText(file);
        // Reset file input so the same file can be selected again
        event.target.value = ''; 
    };

