// services/payrollService.ts
import { Employee, Settings, AttendanceRecord } from '../types';

interface DateInfo {
    year: number;
    month: number;
    day: number;
}

// Function to get the number of weekdays (Monday to Friday) in a given month and year.
const getWorkingDaysInMonth = (year: number, month: number): number => {
    let workingDays = 0;
    const date = new Date(year, month - 1, 1);
    while (date.getMonth() === month - 1) {
        const dayOfWeek = date.getDay();
        if (dayOfWeek !== 0 && dayOfWeek !== 6) { // Sunday = 0, Saturday = 6
            workingDays++;
        }
        date.setDate(date.getDate() + 1);
    }
    return workingDays;
};

export const calculatePayroll = (
    employee: Employee,
    settings: Settings,
    year: number,
    month: number
): number => {
    if (!employee || !settings) {
        return 0; // Or handle the error appropriately
    }

    const { monthlySalary, attendance } = employee;
    const { standardDailyHours, overtimeMultiplier } = settings;
    const numberOfWorkingDays = getWorkingDaysInMonth(year, month);
    const dailyRate = monthlySalary / numberOfWorkingDays;
    const hourlyRate = dailyRate / standardDailyHours;
    let totalPay = monthlySalary;

    for (let day = 1; day <= new Date(year, month, 0).getDate(); day++) {
        const dateString = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        const attendanceRecord = attendance.find(record => record.date === dateString);

        if (attendanceRecord) {
            const { status, checkIn, checkOut } = attendanceRecord;

            if (status === 'absent') {
                totalPay -= dailyRate;
            } else if (status === 'custom') {
                if (checkIn && checkOut) {
                    const [checkInHour, checkInMinute] = checkIn.split(':').map(Number);
                    const [checkOutHour, checkOutMinute] = checkOut.split(':').map(Number);
                    let totalHoursWorked = (checkOutHour - checkInHour) + (checkOutMinute - checkInMinute) / 60;

                    if (totalHoursWorked < 0) {
                        totalHoursWorked += 24;  // Handle cases where check-out is on the next day
                    }

                    if (totalHoursWorked > standardDailyHours) {
                        const overtimeHours = totalHoursWorked - standardDailyHours;
                        totalPay += overtimeHours * hourlyRate * overtimeMultiplier;
                    }
                     else if (totalHoursWorked < standardDailyHours) {
                        totalPay -= (standardDailyHours - totalHoursWorked) * hourlyRate; // deduct based on hourly rate
                    }
                }
            }
        }
    }

    return totalPay;
};
