                }
                return { ...emp, attendance: newAttendance };
            }
            return emp;
        }));
    };

    const weekDays = ['Paz', 'Salı', 'Çarş', 'Perş', 'Cuma', 'Cmt', 'Paz'];

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50 p-4" onClick={onClose}>
            <div className="bg-gray-800 rounded-lg shadow-xl w-full max-w-2xl mx-auto flex flex-col h-[90vh]" onClick={e => e.stopPropagation()}>
                <header className="flex justify-between items-center p-4 border-b border-gray-700">
                    <h2 className="text-xl font-bold text-teal-400">{employee.name} - Puantaj Cetveli</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white"><XIcon /></button>
                </header>
                <div className="p-4 overflow-y-auto flex-grow">
                    <ul className="space-y-2">
                        {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(day => {
                            const date = new Date(year, month, day);
                            const dateString = date.toISOString().split('T')[0];
                            const dayOfWeek = date.getDay();
                            const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
                            const record = employee.attendance.find(a => a.date === dateString);
                            const status = record?.status || 'present';

                            return (
                                <li key={day} className={`p-3 rounded-lg flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 ${isWeekend ? 'bg-gray-700/50' : 'bg-gray-700'}`}>
                                    <div className="flex items-center gap-3">
                                        <div className={`text-center font-bold p-2 rounded-md w-12 ${isWeekend ? 'bg-gray-600' : 'bg-teal-600'}`}>
                                            <div className="text-xl">{day}</div>
                                            <div className="text-xs">{weekDays[dayOfWeek]}</div>
                                        </div>
                                        {isWeekend && <div className="text-sm text-gray-500">Hafta Sonu</div>}
                                    </div>
                                    <div className="flex flex-wrap items-center gap-2">
                                        <select 
                                            value={status}
                                            onChange={(e) => handleAttendanceChange(dateString, { status: e.target.value as any })}
                                            className="bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                        >
                                            <option value="present">Geldi</option>
                                            <option value="absent">Gelmedi</option>
                                            <option value="custom">Özel Giriş/Çıkış</option>
                                        </select>
                                        {status === 'custom' && (
                                            <div className="flex items-center gap-2">
                                                <input type="time" value={record?.checkIn || defaultCheckIn} onChange={(e) => handleAttendanceChange(dateString, { checkIn: e.target.value })} className="bg-gray-600 text-gray-200 rounded-md p-2 w-28"/>
                                                <span>-</span>
                                                <input type="time" value={record?.checkOut || defaultCheckOut} onChange={(e) => handleAttendanceChange(dateString, { checkOut: e.target.value })} className="bg-gray-600 text-gray-200 rounded-md p-2 w-28"/>
                                            </div>
                                        )}
                                    </div>
                                </li>
                            );
                        })}
                    </ul>
                </div>
            </div>
        </div>
    );
};


