import React, { useState, useMemo, useEffect } from 'react';
import type { Employee, Settings, AttendanceRecord } from '../types';
import { calculatePayroll } from '../services/payrollService';
import { XIcon } from './Icons';

interface PayrollScreenProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  settings: Settings;
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', {
        style: 'decimal',
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(amount);
};

// Modal for editing attendance
const AttendanceModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    employee: Employee;
    setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
    currentDate: Date;
    settings: Settings;
}> = ({ isOpen, onClose, employee, setEmployees, currentDate, settings }) => {
    // Local state for immediate UI feedback
    const [monthlyRecords, setMonthlyRecords] = useState<AttendanceRecord[]>(employee.attendance);

    // Effect to propagate local changes to the parent state
    useEffect(() => {
        // This check prevents an infinite loop by only updating if the actual data has changed.
        if (JSON.stringify(monthlyRecords) !== JSON.stringify(employee.attendance)) {
            setEmployees(prev => prev.map(emp => 
                emp.id === employee.id ? { ...emp, attendance: monthlyRecords } : emp
            ));
        }
    }, [monthlyRecords, employee.id, employee.attendance, setEmployees]);


    if (!isOpen) return null;

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    // Calculate default times based on settings
    const defaultCheckIn = '09:00';
    const checkInHour = 9;
    const checkOutHour = checkInHour + (settings.standardDailyHours || 8);
    const defaultCheckOut = `${String(checkOutHour).padStart(2, '0')}:00`;

    const handleAttendanceChange = (date: string, newRecordData: Partial<AttendanceRecord>) => {
        setMonthlyRecords(prevRecords => {
            const newRecords = [...prevRecords];
            const existingRecordIndex = newRecords.findIndex(a => a.date === date);

            let finalUpdateData = { ...newRecordData };

            // When switching to 'custom', initialize times if they don't exist
            if (finalUpdateData.status === 'custom') {
                const existingRecord = existingRecordIndex > -1 ? newRecords[existingRecordIndex] : {};
                finalUpdateData.checkIn = existingRecord.checkIn || defaultCheckIn;
                finalUpdateData.checkOut = existingRecord.checkOut || defaultCheckOut;
            }

            if (existingRecordIndex > -1) {
                newRecords[existingRecordIndex] = { ...newRecords[existingRecordIndex], ...finalUpdateData };
            } else {
                newRecords.push({ date, ...finalUpdateData } as AttendanceRecord);
            }
            return newRecords;
        });
    };

    const weekDays = ['Paz', 'Salı', 'Çarş', 'Perş', 'Cuma', 'Cmt', 'Paz'];

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50 p-4" onClick={onClose}>
            <div className="bg-gray-800 rounded-lg shadow-xl w-full max-w-2xl mx-auto flex flex-col h-[90vh]" onClick={e => e.stopPropagation()}>
                <header className="flex justify-between items-center p-4 border-b border-gray-700">
                    <h2 className="text-xl font-bold text-teal-400">{employee.name} - Puantaj Cetveli</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white"><XIcon /></button>
                </header>
                <div className="p-4 overflow-y-auto flex-grow">
                    <ul className="space-y-2">
                        {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(day => {
                            const date = new Date(year, month, day);
                            const dateString = date.toISOString().split('T')[0];
                            const dayOfWeek = date.getDay();
                            const isWeekend = settings.weekendDays.includes(dayOfWeek);
                            const record = monthlyRecords.find(a => a.date === dateString);

                            // Determine the selected value for the dropdown
                            const selectValue = record?.status || (isWeekend ? 'weekend_off' : 'present');

                            return (
                                <li key={day} className={`p-3 rounded-lg flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 ${isWeekend ? 'bg-gray-700/50' : 'bg-gray-700'}`}>
                                    <div className="flex items-center gap-3">
                                        <div className={`text-center font-bold p-2 rounded-md w-12 ${isWeekend ? 'bg-gray-600' : 'bg-teal-600'}`}>
                                            <div className="text-xl">{day}</div>
                                            <div className="text-xs">{weekDays[dayOfWeek]}</div>
                                        </div>
                                    </div>
                                    <div className="flex flex-wrap items-center gap-2">
                                        <select 
                                            value={selectValue}
                                            onChange={(e) => handleAttendanceChange(dateString, { status: e.target.value as any })}
                                            className="bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                        >
                                            {isWeekend && !record && <option value="weekend_off" disabled>Hafta Sonu Tatili</option>}
                                            <option value="present">Geldi</option>
                                            <option value="absent">Gelmedi</option>
                                            <option value="custom">Özel Giriş/Çıkış</option>
                                        </select>

                                        {selectValue === 'custom' && (
                                            <div className="flex items-center gap-2">
                                                <input type="time" value={record?.checkIn || defaultCheckIn} onChange={(e) => handleAttendanceChange(dateString, { checkIn: e.target.value })} className="bg-gray-600 text-gray-200 rounded-md p-2 w-28"/>
                                                <span>-</span>
                                                <input type="time" value={record?.checkOut || defaultCheckOut} onChange={(e) => handleAttendanceChange(dateString, { checkOut: e.target.value })} className="bg-gray-600 text-gray-200 rounded-md p-2 w-28"/>
                                            </div>
                                        )}
                                    </div>
                                </li>
                            );
                        })}
                    </ul>
                </div>
            </div>
        </div>
    );
};


const PayrollScreen: React.FC<PayrollScreenProps> = ({ employees, setEmployees, settings }) => {
    const [currentDate, setCurrentDate] = useState(new Date());
    const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);

    const handlePrevMonth = () => {
        setCurrentDate(prev => new Date(prev.getFullYear(), prev.getMonth() - 1, 1));
    };

    const handleNextMonth = () => {
        setCurrentDate(prev => new Date(prev.getFullYear(), prev.getMonth() + 1, 1));
    };

    const monthName = currentDate.toLocaleString('tr-TR', { month: 'long', year: 'numeric' });

    const sortedEmployees = useMemo(() => {
        return [...employees].sort((a, b) => a.name.localeCompare(b.name));
    }, [employees]);

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-teal-400">Puantaj & Maaş</h2>
                <div className="flex items-center gap-2">
                    <button onClick={handlePrevMonth} className="px-3 py-1 bg-gray-700 rounded-md hover:bg-gray-600">&lt;</button>
                    <span className="font-semibold w-32 text-center">{monthName}</span>
                    <button onClick={handleNextMonth} className="px-3 py-1 bg-gray-700 rounded-md hover:bg-gray-600">&gt;</button>
                </div>
            </div>

            {employees.length === 0 ? (
                <p className="text-gray-500 text-center py-4">Maaş hesaplamak için önce personel eklemelisiniz.</p>
            ) : (
                <ul className="space-y-4">
                    {sortedEmployees.map(employee => {
                        const payroll = calculatePayroll(employee, settings, currentDate.getFullYear(), currentDate.getMonth());
                        return (
                            <li key={employee.id} className="bg-gray-800 p-4 rounded-lg shadow-md">
                                <div className="flex justify-between items-center mb-3">
                                    <div>
                                        <h3 className="font-bold text-lg text-gray-200">{employee.name}</h3>
                                        <p className="text-xs text-gray-400">Aylık Maaş: {formatCurrency(employee.monthlySalary)}</p>
                                    </div>
                                    <button onClick={() => setSelectedEmployee(employee)} className="px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500">
                                        Puantajı Düzenle
                                    </button>
                                </div>
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-center text-sm">
                                    <div className="bg-gray-700 p-2 rounded-md">
                                        <p className="text-xs text-gray-400">Fazla Mesai</p>
                                        <p className="font-semibold text-green-400">{formatCurrency(payroll.overtimePay)}</p>
                                        <p className="text-xs text-gray-500">({payroll.totalOvertimeHours.toFixed(1)} sa)</p>
                                    </div>
                                    <div className="bg-gray-700 p-2 rounded-md">
                                        <p className="text-xs text-gray-400">Devamsızlık</p>
                                        <p className="font-semibold text-yellow-400">- {formatCurrency(payroll.absenceDeduction)}</p>
                                         <p className="text-xs text-gray-500">({payroll.totalAbsenceDays} gün)</p>
                                    </div>
                                    <div className="bg-gray-700 p-2 rounded-md">
                                        <p className="text-xs text-gray-400">Avans Kesintisi</p>
                                        <p className="font-semibold text-yellow-400">- {formatCurrency(payroll.advanceDeduction)}</p>
                                    </div>
                                    <div className="bg-teal-800/50 p-2 rounded-md border border-teal-500">
                                        <p className="text-xs text-teal-300">Net Ödenecek</p>
                                        <p className="font-bold text-xl text-white">{formatCurrency(payroll.finalPay)}</p>
                                    </div>
                                </div>
                            </li>
                        );
                    })}
                </ul>
            )}

            {selectedEmployee && (
                <AttendanceModal 
                    isOpen={!!selectedEmployee}
                    onClose={() => setSelectedEmployee(null)}
                    employee={selectedEmployee}
                    setEmployees={setEmployees}
                    currentDate={currentDate}
                    settings={settings}
                />
            )}
        </div>
    );
};

