    minutesPer100Meters: number;
    notificationLeadTimeMinutes: number;
    requirePasswordForDelete: boolean;
    confirmationPassword?: string;
    standardDailyHours: number;
    overtimeMultiplier: number;
    absenceMultiplier: number;
    undertimeMultiplier: number;
    weekendDays: number[]; // 0: Sunday, 1: Monday, ..., 6: Saturday
