// Helper to get number of weekdays in a month based on settings
const getWorkingDaysInMonth = (year: number, month: number, weekendDays: number[]): number => {
    const date = new Date(year, month, 1);
    let workingDays = 0;
    while (date.getMonth() === month) {
        const dayOfWeek = date.getDay();
        if (!weekendDays.includes(dayOfWeek)) {
            workingDays++;
        }
        date.setDate(date.getDate() + 1);
    }
    return workingDays;
};

export const calculatePayroll = (
    employee: Employee,
    settings: Settings,
    year: number,
    month: number // 0-indexed (0 for January)
) => {
    if (!employee.monthlySalary || employee.monthlySalary <= 0) {
        return {
            baseSalary: 0,
            overtimePay: 0,
            undertimeDeduction: 0,
            absenceDeduction: 0,
            advanceDeduction: 0,
            finalPay: 0,
            totalOvertimeHours: 0,
            totalUndertimeHours: 0,
            totalAbsenceDays: 0,
        };
    }

    const workingDaysInMonth = getWorkingDaysInMonth(year, month, settings.weekendDays);
    if (workingDaysInMonth === 0) {
         return {
            baseSalary: employee.monthlySalary,
            overtimePay: 0,
            undertimeDeduction: 0,
            absenceDeduction: 0,
            advanceDeduction: 0,
            finalPay: employee.monthlySalary,
            totalOvertimeHours: 0,
            totalUndertimeHours: 0,
            totalAbsenceDays: 0,
        };
    }

    const dailyRate = employee.monthlySalary / workingDaysInMonth;
    const hourlyRate = dailyRate / settings.standardDailyHours;

    let overtimePay = 0;
    let undertimeDeduction = 0;
    let absenceDeduction = 0;
    let totalOvertimeHours = 0;
    let totalUndertimeHours = 0;
    let totalAbsenceDays = 0;

    const daysInMonth = new Date(year, month + 1, 0).getDate();

    for (let day = 1; day <= daysInMonth; day++) {
        const currentDate = new Date(year, month, day);
        const dateString = currentDate.toISOString().split('T')[0]; // YYYY-MM-DD
        const dayOfWeek = currentDate.getDay();
        const isWeekend = settings.weekendDays.includes(dayOfWeek);

        const attendanceRecord = employee.attendance.find(a => a.date === dateString);

        if (isWeekend) {
            // Only process if there's an explicit record of work on a weekend
            if (attendanceRecord && attendanceRecord.status !== 'absent') {
                let workedHours = settings.standardDailyHours; // Default for 'present' status on weekend

                if (attendanceRecord.status === 'custom' && attendanceRecord.checkIn && attendanceRecord.checkOut) {
                    const [inHours, inMinutes] = attendanceRecord.checkIn.split(':').map(Number);
                    const [outHours, outMinutes] = attendanceRecord.checkOut.split(':').map(Number);
                    const checkInTime = new Date(0,0,0, inHours, inMinutes);
                    const checkOutTime = new Date(0,0,0, outHours, outMinutes);
                    if (checkOutTime < checkInTime) { checkOutTime.setDate(checkOutTime.getDate() + 1); }
                    workedHours = (checkOutTime.getTime() - checkInTime.getTime()) / (1000 * 60 * 60);
                }

                const overtimeHours = workedHours; // All weekend work is overtime
                if (overtimeHours > 0) {
                    totalOvertimeHours += overtimeHours;
                    overtimePay += overtimeHours * hourlyRate * settings.overtimeMultiplier;
                }
            }
        } else { // It's a working day
            if (attendanceRecord?.status === 'absent') {
                totalAbsenceDays++;
                absenceDeduction += dailyRate * (settings.absenceMultiplier || 1);
            } else if (attendanceRecord?.status === 'custom' && attendanceRecord.checkIn && attendanceRecord.checkOut) {
                const [inHours, inMinutes] = attendanceRecord.checkIn.split(':').map(Number);
                const [outHours, outMinutes] = attendanceRecord.checkOut.split(':').map(Number);
                const checkInTime = new Date(0);
                checkInTime.setHours(inHours, inMinutes, 0, 0);
                const checkOutTime = new Date(0);
                checkOutTime.setHours(outHours, outMinutes, 0, 0);

                if (checkOutTime < checkInTime) { checkOutTime.setDate(checkOutTime.getDate() + 1); }

                const workedHours = (checkOutTime.getTime() - checkInTime.getTime()) / (1000 * 60 * 60);
                const overtimeHours = Math.max(0, workedHours - settings.standardDailyHours);
                const undertimeHours = Math.max(0, settings.standardDailyHours - workedHours);

                if (overtimeHours > 0) {
                    totalOvertimeHours += overtimeHours;
                    overtimePay += overtimeHours * hourlyRate * settings.overtimeMultiplier;
                }
                if (undertimeHours > 0) {
                    totalUndertimeHours += undertimeHours;
                    undertimeDeduction += undertimeHours * hourlyRate * (settings.undertimeMultiplier || 1);
                }
            }
            // If status is 'present' or no record, it's a normal workday, already accounted for in baseSalary.
        }
    }

    const advanceDeduction = employee.advances.reduce((sum, adv) => {
        const advDate = new Date(adv.date);
        if (advDate.getFullYear() === year && advDate.getMonth() === month) {
            return sum + adv.amount;
        }
        return sum;
    }, 0);

    const finalPay = employee.monthlySalary + overtimePay - absenceDeduction - undertimeDeduction - advanceDeduction;

    return {
        baseSalary: employee.monthlySalary,
        overtimePay,
        undertimeDeduction,
        absenceDeduction,
        advanceDeduction,
        finalPay,
        totalOvertimeHours,
        totalUndertimeHours,
        totalAbsenceDays
    };
};

