import React, { useState, useMemo, useEffect } from 'react';
import type { Employee, Settings, AttendanceRecord } from '../types';
import { calculatePayroll } from '../services/payrollService';
import { XIcon } from './Icons';

interface PayrollScreenProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  settings: Settings;
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', {
        style: 'decimal',
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(amount);
};

// Modal for editing attendance
const AttendanceModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    employee: Employee;
    setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
    currentDate: Date;
    settings: Settings;
}> = ({ isOpen, onClose, employee, setEmployees, currentDate, settings }) => {
    // Local state for immediate UI feedback
    const [monthlyRecords, setMonthlyRecords] = useState<AttendanceRecord[]>(employee.attendance);

    // Effect to propagate local changes to the parent state
    useEffect(() => {
        // This check prevents an infinite loop by only updating if the actual data has changed.
        if (JSON.stringify(monthlyRecords) !== JSON.stringify(employee.attendance)) {
            setEmployees(prev => prev.map(emp => 
                emp.id === employee.id ? { ...emp, attendance: monthlyRecords } : emp
            ));
        }
    }, [monthlyRecords, employee.id, employee.attendance, setEmployees]);


    if (!isOpen) return null;

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    // Calculate default times based on settings
    const defaultCheckIn = '09:00';
    const checkInHour = 9;
    const checkOutHour = checkInHour + (settings.standardDailyHours || 8);
    const defaultCheckOut = `${String(checkOutHour).padStart(2, '0')}:00`;

    const handleAttendanceChange = (date: string, newRecordData: Partial<AttendanceRecord>) => {
        setMonthlyRecords(prevRecords => {
            const newRecords = [...prevRecords];
            const existingRecordIndex = newRecords.findIndex(a => a.date === date);

            let finalUpdateData = { ...newRecordData };

            // When switching to 'custom', initialize times if they don't exist
            if (finalUpdateData.status === 'custom') {
                const existingRecord = existingRecordIndex > -1 ? newRecords[existingRecordIndex] : {};
                finalUpdateData.checkIn = existingRecord.checkIn || defaultCheckIn;
                finalUpdateData.checkOut = existingRecord.checkOut || defaultCheckOut;
            }

            if (existingRecordIndex > -1) {
                newRecords[existingRecordIndex] = { ...newRecords[existingRecordIndex], ...finalUpdateData };
            } else {
                newRecords.push({ date, ...finalUpdateData } as AttendanceRecord);
            }
            return newRecords;
        });
    };

    const weekDays = ['Paz', 'Salı', 'Çarş', 'Perş', 'Cuma', 'Cmt', 'Paz'];

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50 p-4" onClick={onClose}>
            <div className="bg-gray-800 rounded-lg shadow-xl w-full max-w-2xl mx-auto flex flex-col h-[90vh]" onClick={e => e.stopPropagation()}>
                <header className="flex justify-between items-center p-4 border-b border-gray-700">
                    <h2 className="text-xl font-bold text-teal-400">{employee.name} - Puantaj Cetveli</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white"><XIcon /></button>
                </header>
                <div className="p-4 overflow-y-auto flex-grow">
                    <ul className="space-y-2">
