import type { Employee, Settings, AttendanceRecord } from '../types';

// Helper to get number of weekdays in a month based on settings
const getWorkingDaysInMonth = (year: number, month: number, weekendDays: number[]): number => {
    const date = new Date(year, month, 1);
    let workingDays = 0;
    while (date.getMonth() === month) {
        const dayOfWeek = date.getDay();
        if (!weekendDays.includes(dayOfWeek)) {
            workingDays++;
        }
        date.setDate(date.getDate() + 1);
    }
    return workingDays;
};

export const calculatePayroll = (
    employee: Employee,
    settings: Settings,
    year: number,
    month: number // 0-indexed (0 for January)
) => {
    if (!employee.monthlySalary || employee.monthlySalary <= 0) {
        return {
            baseSalary: 0,
            overtimePay: 0,
            undertimeDeduction: 0,
            absenceDeduction: 0,
            advanceDeduction: 0,
            finalPay: 0,
            totalOvertimeHours: 0,
            totalUndertimeHours: 0,
            totalAbsenceDays: 0,
        };
    }

    const workingDaysInMonth = getWorkingDaysInMonth(year, month, settings.weekendDays);
    if (workingDaysInMonth === 0) {
         return {
            baseSalary: employee.monthlySalary,
            overtimePay: 0,
            undertimeDeduction: 0,
            absenceDeduction: 0,
            advanceDeduction: 0,
            finalPay: employee.monthlySalary,
            totalOvertimeHours: 0,
            totalUndertimeHours: 0,
            totalAbsenceDays: 0,
        };
    }

    const dailyRate = employee.monthlySalary / workingDaysInMonth;
    const hourlyRate = dailyRate / settings.standardDailyHours;

    let overtimePay = 0;
    let undertimeDeduction = 0;
    let absenceDeduction = 0;
    let totalOvertimeHours = 0;
    let totalUndertimeHours = 0;
    let totalAbsenceDays = 0;

    const daysInMonth = new Date(year, month + 1, 0).getDate();

    for (let day = 1; day <= daysInMonth; day++) {
        const currentDate = new Date(year, month, day);
        const dateString = currentDate.toISOString().split('T')[0]; // YYYY-MM-DD
        const dayOfWeek = currentDate.getDay();
        const isWeekend = settings.weekendDays.includes(dayOfWeek);

        const attendanceRecord = employee.attendance.find(a => a.date === dateString);

        if (isWeekend) {
            // Only process if there's an explicit record of work on a weekend
            if (attendanceRecord && attendanceRecord.status !== 'absent') {
                let workedHours = settings.standardDailyHours; // Default for 'present' status on weekend

                if (attendanceRecord.status === 'custom') {
                    if (attendanceRecord.workedHours != null && attendanceRecord.workedHours > 0) {
                        workedHours = attendanceRecord.workedHours;
                    } else if (attendanceRecord.checkIn && attendanceRecord.checkOut) {
                        const [inHours, inMinutes] = attendanceRecord.checkIn.split(':').map(Number);
                        const [outHours, outMinutes] = attendanceRecord.checkOut.split(':').map(Number);
                        const checkInTime = new Date(0,0,0, inHours, inMinutes);
                        const checkOutTime = new Date(0,0,0, outHours, outMinutes);
                        if (checkOutTime < checkInTime) { checkOutTime.setDate(checkOutTime.getDate() + 1); }
                        workedHours = (checkOutTime.getTime() - checkInTime.getTime()) / (1000 * 60 * 60);
                    }
                }

                const overtimeHours = workedHours; // All weekend work is overtime
                if (overtimeHours > 0) {
                    totalOvertimeHours += overtimeHours;
                    overtimePay += overtimeHours * hourlyRate * settings.overtimeMultiplier;
                }
            }
        } else { // It's a working day
            if (attendanceRecord?.status === 'absent') {
                totalAbsenceDays++;
                absenceDeduction += dailyRate * (settings.absenceMultiplier || 1);
            } else if (attendanceRecord?.status === 'custom') {
                let workedHours = 0;
                if (attendanceRecord.workedHours != null && attendanceRecord.workedHours > 0) {
                    workedHours = attendanceRecord.workedHours;
                } else if (attendanceRecord.checkIn && attendanceRecord.checkOut) {
                    const [inHours, inMinutes] = attendanceRecord.checkIn.split(':').map(Number);
                    const [outHours, outMinutes] = attendanceRecord.checkOut.split(':').map(Number);
                    const checkInTime = new Date(0);
                    checkInTime.setHours(inHours, inMinutes, 0, 0);
                    const checkOutTime = new Date(0);
                    checkOutTime.setHours(outHours, outMinutes, 0, 0);

                    if (checkOutTime < checkInTime) { checkOutTime.setDate(checkOutTime.getDate() + 1); }

                    workedHours = (checkOutTime.getTime() - checkInTime.getTime()) / (1000 * 60 * 60);
                }

                if (workedHours > 0) {
                    const overtimeHours = Math.max(0, workedHours - settings.standardDailyHours);
                    const undertimeHours = Math.max(0, settings.standardDailyHours - workedHours);

                    if (overtimeHours > 0) {
                        totalOvertimeHours += overtimeHours;
                        overtimePay += overtimeHours * hourlyRate * settings.overtimeMultiplier;
                    }
                    if (undertimeHours > 0) {
                        totalUndertimeHours += undertimeHours;
                        undertimeDeduction += undertimeHours * hourlyRate * (settings.undertimeMultiplier || 1);
                    }
                }
            }
            // If status is 'present' or no record, it's a normal workday, already accounted for in baseSalary.
        }
    }

    const advanceDeduction = employee.advances.reduce((sum, adv) => {
        const advDate = new Date(adv.date);
        if (advDate.getFullYear() === year && advDate.getMonth() === month) {
            return sum + adv.amount;
        }
        return sum;
    }, 0);

    const finalPay = employee.monthlySalary + overtimePay - absenceDeduction - undertimeDeduction - advanceDeduction;

    return {
        baseSalary: employee.monthlySalary,
        overtimePay,
        undertimeDeduction,
        absenceDeduction,
        advanceDeduction,
        finalPay,
        totalOvertimeHours,
        totalUndertimeHours,
        totalAbsenceDays
    };
};

import React, { useState, useMemo, useEffect } from 'react';
import type { Employee, Settings, AttendanceRecord } from '../types';
import { calculatePayroll } from '../services/payrollService';
import { XIcon } from './Icons';

interface PayrollScreenProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  settings: Settings;
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', {
        style: 'decimal',
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(amount);
};

// Modal for editing attendance
const AttendanceModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    employee: Employee;
    setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
    currentDate: Date;
    settings: Settings;
}> = ({ isOpen, onClose, employee, setEmployees, currentDate, settings }) => {
    const [monthlyRecords, setMonthlyRecords] = useState<AttendanceRecord[]>(employee.attendance);

    useEffect(() => {
        if (JSON.stringify(monthlyRecords) !== JSON.stringify(employee.attendance)) {
            setEmployees(prev => prev.map(emp => 
                emp.id === employee.id ? { ...emp, attendance: monthlyRecords } : emp
            ));
        }
    }, [monthlyRecords, employee.id, employee.attendance, setEmployees]);


    if (!isOpen) return null;

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const defaultCheckIn = '09:00';
    const checkInHour = 9;
    const checkOutHour = checkInHour + (settings.standardDailyHours || 8);
    const defaultCheckOut = `${String(checkOutHour).padStart(2, '0')}:00`;

    const handleAttendanceChange = (date: string, newRecordData: Partial<AttendanceRecord>) => {
        setMonthlyRecords(prevRecords => {
            const newRecords = [...prevRecords];
            const existingRecordIndex = newRecords.findIndex(a => a.date === date);

            let baseRecord: AttendanceRecord;
            if (existingRecordIndex > -1) {
                baseRecord = { ...newRecords[existingRecordIndex] };
            } else {
                baseRecord = { date, status: 'custom' };
            }

            let updatedRecord = { ...baseRecord, ...newRecordData };

            if (newRecordData.hasOwnProperty('workedHours')) {
                updatedRecord.checkIn = undefined;
                updatedRecord.checkOut = undefined;
                if (updatedRecord.workedHours === undefined || isNaN(updatedRecord.workedHours) || updatedRecord.workedHours <= 0) {
                    updatedRecord.workedHours = undefined;
                    updatedRecord.checkIn = defaultCheckIn;
                    updatedRecord.checkOut = defaultCheckOut;
                }
            } else if (newRecordData.hasOwnProperty('checkIn') || newRecordData.hasOwnProperty('checkOut')) {
                updatedRecord.workedHours = undefined;
            }

            if(newRecordData.status === 'custom' && baseRecord.status !== 'custom') {
                updatedRecord.checkIn = updatedRecord.checkIn || defaultCheckIn;
                updatedRecord.checkOut = updatedRecord.checkOut || defaultCheckOut;
            }

            if (existingRecordIndex > -1) {
                newRecords[existingRecordIndex] = updatedRecord;
            } else {
                newRecords.push(updatedRecord);
            }
            return newRecords;
        });
    };

    const weekDays = ['Paz', 'Salı', 'Çarş', 'Perş', 'Cuma', 'Cmt', 'Paz'];

    return (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50 p-4" onClick={onClose}>
            <div className="bg-gray-800 rounded-lg shadow-xl w-full max-w-2xl mx-auto flex flex-col h-[90vh]" onClick={e => e.stopPropagation()}>
                <header className="flex justify-between items-center p-4 border-b border-gray-700">
                    <h2 className="text-xl font-bold text-teal-400">{employee.name} - Puantaj Cetveli</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white"><XIcon /></button>
                </header>
                <div className="p-4 overflow-y-auto flex-grow">
                    <ul className="space-y-2">
                        {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(day => {
                            const date = new Date(year, month, day);
                            const dateString = date.toISOString().split('T')[0];
                            const dayOfWeek = date.getDay();
                            const isWeekend = settings.weekendDays.includes(dayOfWeek);
                            const record = monthlyRecords.find(a => a.date === dateString);

                            const selectValue = record?.status || (isWeekend ? 'weekend_off' : 'present');

                            return (
                                <li key={day} className={`p-3 rounded-lg flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 ${isWeekend ? 'bg-gray-700/50' : 'bg-gray-700'}`}>
                                    <div className="flex items-center gap-3">
                                        <div className={`text-center font-bold p-2 rounded-md w-12 ${isWeekend ? 'bg-gray-600' : 'bg-teal-600'}`}>
                                            <div className="text-xl">{day}</div>
                                            <div className="text-xs">{weekDays[dayOfWeek]}</div>
                                        </div>
                                    </div>
                                    <div className="flex flex-col gap-2">
                                        <select 
                                            value={selectValue}
                                            onChange={(e) => handleAttendanceChange(dateString, { status: e.target.value as any })}
                                            className="bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                        >
                                            {isWeekend && !record && <option value="weekend_off" disabled>Hafta Sonu Tatili</option>}
                                            <option value="present">Geldi</option>
                                            <option value="absent">Gelmedi</option>
                                            <option value="custom">Özel Giriş/Çıkış</option>
                                        </select>

                                        {selectValue === 'custom' && (
                                            <div className="flex flex-col gap-2 mt-2">
                                                <div className="flex items-center gap-2">
                                                    <input type="time" value={record?.checkIn || ''} disabled={!!record?.workedHours} onChange={(e) => handleAttendanceChange(dateString, { checkIn: e.target.value })} className="bg-gray-600 text-gray-200 rounded-md p-2 w-28 disabled:opacity-50"/>
                                                    <span>-</span>
                                                    <input type="time" value={record?.checkOut || ''} disabled={!!record?.workedHours} onChange={(e) => handleAttendanceChange(dateString, { checkOut: e.target.value })} className="bg-gray-600 text-gray-200 rounded-md p-2 w-28 disabled:opacity-50"/>
                                                </div>
                                                <div className="flex items-center gap-2 text-gray-400 text-xs my-1">
                                                    <div className="h-px flex-grow bg-gray-600"></div>
                                                    <span>VEYA</span>
                                                    <div className="h-px flex-grow bg-gray-600"></div>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <input type="number" step="0.1" value={record?.workedHours ?? ''} onChange={(e) => handleAttendanceChange(dateString, { workedHours: e.target.value ? parseFloat(e.target.value) : undefined })} placeholder="Toplam saat" className="bg-gray-600 text-gray-200 rounded-md p-2 w-28"/>
                                                    <label className="text-sm text-gray-400">Çalışma Süresi (saat)</label>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </li>
                            );
                        })}
                    </ul>
                </div>
            </div>
        </div>
    );
};


