export type View = 'home' | 'assistant' | 'customers' | 'customerDetail' | 'patterns' | 'settings' | 'advances' | 'payroll';

import React, { useState, useMemo } from 'react';
import type { Employee, Advance, Settings } from '../types';
import { PlusIcon, ChevronDownIcon, TrashIcon, EditIcon, SaveIcon, XIcon } from './Icons';
import ConfirmationModal from './ConfirmationModal';

interface EmployeeAdvanceScreenProps {
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  settings: Settings;
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', {
        style: 'decimal',
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(amount);
};

const formatDate = (isoString: string) => {
    if (!isoString) return '';
    const date = new Date(isoString);
    return date.toLocaleDateString('tr-TR', {
        day: '2-digit',
        month: 'long',
        year: 'numeric'
    });
};

const EmployeeAdvanceScreen: React.FC<EmployeeAdvanceScreenProps> = ({ employees, setEmployees, settings }) => {
    const [newEmployeeName, setNewEmployeeName] = useState('');
    const [newEmployeeSalary, setNewEmployeeSalary] = useState('');
    const [isNewHire, setIsNewHire] = useState(false);
    const [newEmployeeStartDate, setNewEmployeeStartDate] = useState('');

    const [expandedEmployeeId, setExpandedEmployeeId] = useState<string | null>(null);
    const [advanceToDelete, setAdvanceToDelete] = useState<{ employeeId: string; advanceId: string } | null>(null);
    const [employeeToDelete, setEmployeeToDelete] = useState<Employee | null>(null);

    // State for editing employee name
    const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
    const [editedEmployeeName, setEditedEmployeeName] = useState('');
    const [editedEmployeeSalary, setEditedEmployeeSalary] = useState('');

    // Form state for adding an advance
    const [advanceAmount, setAdvanceAmount] = useState('');
    const [advanceDescription, setAdvanceDescription] = useState('');

    const handleAddEmployee = (e: React.FormEvent) => {
        e.preventDefault();
        const salary = parseFloat(newEmployeeSalary);
        if (newEmployeeName.trim() === '' || isNaN(salary) || salary < 0) {
            alert('Lütfen geçerli bir personel adı ve aylık maaş girin.');
            return;
        }
        if (isNewHire && !newEmployeeStartDate) {
            alert('Lütfen yeni personelin işe başlama tarihini girin.');
            return;
        }

        const newEmployee: Employee = {
            id: Date.now().toString(),
            name: newEmployeeName.trim(),
            monthlySalary: salary,
            startDate: isNewHire ? newEmployeeStartDate : undefined,
            advances: [],
            attendance: [],
        };
        setEmployees(prev => [newEmployee, ...prev].sort((a,b) => a.name.localeCompare(b.name)));
        setNewEmployeeName('');
        setNewEmployeeSalary('');
        setIsNewHire(false);
        setNewEmployeeStartDate('');
    };

    const handleToggleEmployee = (employeeId: string) => {
        if (editingEmployeeId === employeeId) return; // Don't toggle if editing

        if (expandedEmployeeId === employeeId) {
            setExpandedEmployeeId(null);
        } else {
            setExpandedEmployeeId(employeeId);
            // Reset form when opening a new one
            setAdvanceAmount('');
            setAdvanceDescription('');
        }
    };

    const handleEditRequest = (employee: Employee) => {
        setEditingEmployeeId(employee.id);
        setEditedEmployeeName(employee.name);
        setEditedEmployeeSalary(employee.monthlySalary.toString());
        setExpandedEmployeeId(null); // Close accordion when editing
    };

    const handleCancelEdit = () => {
        setEditingEmployeeId(null);
        setEditedEmployeeName('');
        setEditedEmployeeSalary('');
    };

    const handleSaveEmployee = (employeeId: string) => {
        const salary = parseFloat(editedEmployeeSalary);
        if (editedEmployeeName.trim() === '' || isNaN(salary) || salary < 0) {
            alert('Lütfen geçerli bir ad ve maaş girin.');
            return;
        }
        setEmployees(prev => prev.map(emp => 
            emp.id === employeeId ? { ...emp, name: editedEmployeeName.trim(), monthlySalary: salary } : emp
        ));
        handleCancelEdit();
    };


    const handleAddAdvance = (employeeId: string) => {
        const amount = parseFloat(advanceAmount);
        if (isNaN(amount) || amount <= 0) {
            alert("Lütfen geçerli bir avans tutarı girin.");
            return;
        }

        const newAdvance: Advance = {
            id: Date.now().toString(),
            amount: amount,
            date: new Date().toISOString(),
            description: advanceDescription.trim() || undefined,
        };

        setEmployees(prev => prev.map(emp => {
            if (emp.id === employeeId) {
                return { ...emp, advances: [newAdvance, ...emp.advances] };
            }
            return emp;
        }));

        // Reset form
        setAdvanceAmount('');
        setAdvanceDescription('');
    };

    const handleDeleteAdvanceRequest = (employeeId: string, advanceId: string) => {
        setAdvanceToDelete({ employeeId, advanceId });
    };

    const handleConfirmAdvanceDelete = () => {
        if (!advanceToDelete) return;
        const { employeeId, advanceId } = advanceToDelete;

        setEmployees(prev => prev.map(emp => {
            if (emp.id === employeeId) {
                return {
                    ...emp,
                    advances: emp.advances.filter(adv => adv.id !== advanceId)
                };
            }
            return emp;
        }));

        setAdvanceToDelete(null);
    };

    const handleDeleteEmployeeRequest = (employee: Employee) => {
        setEmployeeToDelete(employee);
    };

    const handleConfirmEmployeeDelete = () => {
        if (!employeeToDelete) return;
        setEmployees(prev => prev.filter(emp => emp.id !== employeeToDelete.id));
        setEmployeeToDelete(null);
    };

    const sortedEmployees = useMemo(() => {
        return [...employees].sort((a, b) => a.name.localeCompare(b.name));
    }, [employees]);

    return (
        <div>
            <h2 className="text-2xl font-bold text-teal-400 mb-6">Personel Avans Takibi</h2>

            <form onSubmit={handleAddEmployee} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 space-y-3">
                <div className="flex flex-col sm:flex-row gap-3">
                    <input
                        type="text"
                        value={newEmployeeName}
                        onChange={(e) => setNewEmployeeName(e.target.value)}
                        placeholder="Yeni Personel Adı"
                        className="flex-grow bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
                    />
                     <input
                        type="number"
                        step="0.01"
                        value={newEmployeeSalary}
                        onChange={(e) => setNewEmployeeSalary(e.target.value)}
                        placeholder="Aylık Maaş"
                        className="sm:w-1/3 bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
                    />
                    <button type="submit" className="flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 transition-colors disabled:opacity-50" disabled={!newEmployeeName.trim() || !newEmployeeSalary.trim()}>
                        <PlusIcon /> Ekle
                    </button>
                </div>
                <div className="flex items-center gap-4">
                    <label className="flex items-center gap-2 text-sm text-gray-300 cursor-pointer">
                        <input
                            type="checkbox"
                            checked={isNewHire}
                            onChange={(e) => setIsNewHire(e.target.checked)}
                            className="h-4 w-4 rounded bg-gray-600 border-gray-500 text-teal-500 focus:ring-teal-600"
                        />
                        Yeni İşe Başladı
                    </label>
                    {isNewHire && (
                         <input
                            type="date"
                            value={newEmployeeStartDate}
                            onChange={(e) => setNewEmployeeStartDate(e.target.value)}
                            className="bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
                            required
                        />
                    )}
                </div>
            </form>

            {employees.length === 0 ? (
                <p className="text-gray-500 text-center py-4">Henüz personel eklenmemiş.</p>
            ) : (
                <ul className="space-y-3">
                    {sortedEmployees.map(employee => {
                        const totalAdvance = employee.advances.reduce((sum, adv) => sum + adv.amount, 0);
                        const isExpanded = expandedEmployeeId === employee.id;
                        const isEditing = editingEmployeeId === employee.id;

                        return (
                            <li key={employee.id} className="bg-gray-800 rounded-lg shadow-md transition-all">
                                <div className="p-4 flex justify-between items-center">
                                    <div className="flex-grow">
                                        {isEditing ? (
                                            <div className="flex items-center gap-2">
                                                <input
                                                    type="text"
                                                    value={editedEmployeeName}
                                                    onChange={(e) => setEditedEmployeeName(e.target.value)}
                                                    className="flex-grow bg-gray-600 text-gray-200 rounded-md p-1 text-lg font-bold focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                                    autoFocus
                                                />
                                                <input
                                                    type="number"
                                                    step="0.01"
                                                    value={editedEmployeeSalary}
                                                    onChange={(e) => setEditedEmployeeSalary(e.target.value)}
                                                    placeholder="Aylık Maaş"
                                                    className="w-24 bg-gray-600 text-gray-200 rounded-md p-1 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                                />
                                                <button onClick={() => handleSaveEmployee(employee.id)} className="p-1.5 bg-green-600 text-white rounded-md hover:bg-green-500"><SaveIcon /></button>
                                                <button onClick={handleCancelEdit} className="p-1.5 bg-gray-500 text-white rounded-md hover:bg-gray-400"><XIcon /></button>
                                            </div>
                                        ) : (
                                            <div 
                                                className="flex flex-col items-start gap-1 cursor-pointer group"
                                                onClick={() => handleToggleEmployee(employee.id)}
                                            >
                                                <div className="flex items-center gap-3">
                                                    <h3 className="font-bold text-lg text-gray-200 group-hover:text-teal-400">{employee.name}</h3>
                                                    <button onClick={(e) => { e.stopPropagation(); handleEditRequest(employee); }} className="text-gray-500 hover:text-teal-400 opacity-0 group-hover:opacity-100 transition-opacity"><EditIcon /></button>
                                                    <button onClick={(e) => { e.stopPropagation(); handleDeleteEmployeeRequest(employee); }} className="text-gray-500 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><TrashIcon /></button>
                                                </div>
                                                 <div className="text-xs text-gray-400 ml-1 space-x-2">
                                                    <span>Aylık Maaş: {formatCurrency(employee.monthlySalary)}</span>
                                                    {employee.startDate && <span>İşe Giriş: {formatDate(employee.startDate)}</span>}
                                                 </div>
                                            </div>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-4 cursor-pointer" onClick={() => handleToggleEmployee(employee.id)}>
                                        <div className="text-right">
                                            <p className="text-sm text-gray-400">Toplam Avans</p>
                                            <p className="font-semibold text-xl text-red-400">{formatCurrency(totalAdvance)}</p>
                                        </div>
                                        <ChevronDownIcon className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} />
                                    </div>
                                </div>

                                {isExpanded && (
                                    <div className="p-4 border-t border-gray-700 space-y-4">
                                        {/* Add Advance Form */}
                                        <div className="p-3 bg-gray-700/50 rounded-lg space-y-3">
                                            <h4 className="text-md font-semibold text-gray-300">Yeni Avans Ekle</h4>
                                            <div className="flex flex-col sm:flex-row gap-2">
                                                <input
                                                    type="number"
                                                    step="0.01"
                                                    value={advanceAmount}
                                                    onChange={e => setAdvanceAmount(e.target.value)}
                                                    placeholder="Tutar"
                                                    className="w-full sm:w-1/3 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                                />
                                                <input
                                                    type="text"
                                                    value={advanceDescription}
                                                    onChange={e => setAdvanceDescription(e.target.value)}
                                                    placeholder="Açıklama (isteğe bağlı)"
                                                    className="flex-grow bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                                />
                                            </div>
                                            <button 
                                                type="button" 
                                                onClick={() => handleAddAdvance(employee.id)} 
                                                disabled={!advanceAmount}
                                                className="w-full px-3 py-2 bg-teal-600 text-white rounded-md hover:bg-teal-500 disabled:opacity-50"
                                            >
                                                Avansı Kaydet
                                            </button>
                                        </div>

                                        {/* Advance History */}
                                        <div>
                                            <h4 className="text-md font-semibold text-gray-300 mb-2">Avans Geçmişi</h4>
                                            {employee.advances.length > 0 ? (
                                                <ul className="divide-y divide-gray-700/50 max-h-60 overflow-y-auto">
                                                    {employee.advances.map(advance => (
                                                        <li key={advance.id} className="py-2">
                                                            <div className="flex justify-between items-start">
                                                                <div>
                                                                    <p className="font-semibold text-gray-200">{formatCurrency(advance.amount)}</p>
                                                                    {advance.description && <p className="text-xs text-gray-400 mt-1">{advance.description}</p>}
                                                                </div>
                                                                <div className="flex items-center gap-3">
                                                                    <p className="text-xs text-gray-500">{formatDate(advance.date)}</p>
                                                                    <button 
                                                                        onClick={() => handleDeleteAdvanceRequest(employee.id, advance.id)}
                                                                        className="text-gray-500 hover:text-red-500 transition-colors"
                                                                        aria-label="Avansı Sil"
                                                                    >
                                                                        <TrashIcon className="h-4 w-4" />
                                                                    </button>
                                                                </div>
                                                            </div>
                                                        </li>
                                                    ))}
                                                </ul>
                                            ) : (
                                                <p className="text-sm text-gray-500 text-center p-3">Bu personele ait avans kaydı bulunmuyor.</p>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </li>
                        );
                    })}
                </ul>
            )}

            <ConfirmationModal
                isOpen={!!advanceToDelete}
                onClose={() => setAdvanceToDelete(null)}
                onConfirm={handleConfirmAdvanceDelete}
                title="Avansı Silmeyi Onayla"
                settings={settings}
            >
                <p>Bu avans kaydını kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p>
            </ConfirmationModal>

            <ConfirmationModal
                isOpen={!!employeeToDelete}
                onClose={() => setEmployeeToDelete(null)}
                onConfirm={handleConfirmEmployeeDelete}
                title="Personeli Silmeyi Onayla"
                settings={settings}
            >
                <p><strong>{employeeToDelete?.name}</strong> isimli personeli kalıcı olarak silmek istediğinizden emin misiniz?</p>
                <p className="mt-2 font-bold text-red-400">Bu işlem, personele ait tüm avans kayıtlarını da silecektir ve geri alınamaz.</p>
            </ConfirmationModal>
        </div>
    );
};

export default EmployeeAdvanceScreen;

import type { Employee, Settings, AttendanceRecord } from '../types';

// Helper to get number of weekdays in a month based on settings
const getWorkingDaysInMonth = (year: number, month: number, weekendDays: number[]): number => {
    const date = new Date(year, month, 1);
    let workingDays = 0;
    while (date.getMonth() === month) {
        const dayOfWeek = date.getDay();
        if (!weekendDays.includes(dayOfWeek)) {
            workingDays++;
        }
        date.setDate(date.getDate() + 1);
    }
    return workingDays;
};

export const calculatePayroll = (
    employee: Employee,
    settings: Settings,
    year: number,
    month: number // 0-indexed (0 for January)
) => {
    if (!employee.monthlySalary || employee.monthlySalary <= 0) {
        return {
            baseSalary: 0,
            overtimePay: 0,
            undertimeDeduction: 0,
            absenceDeduction: 0,
            advanceDeduction: 0,
            finalPay: 0,
            totalOvertimeHours: 0,
            totalUndertimeHours: 0,
            totalAbsenceDays: 0,
        };
    }

    const workingDaysInMonth = getWorkingDaysInMonth(year, month, settings.weekendDays);
    if (workingDaysInMonth === 0) {
         return {
            baseSalary: employee.monthlySalary,
            overtimePay: 0,
            undertimeDeduction: 0,
            absenceDeduction: 0,
            advanceDeduction: 0,
            finalPay: employee.monthlySalary,
            totalOvertimeHours: 0,
            totalUndertimeHours: 0,
            totalAbsenceDays: 0,
        };
    }

    const dailyRate = employee.monthlySalary / workingDaysInMonth;
    const hourlyRate = dailyRate / settings.standardDailyHours;

    let proratedBaseSalary = employee.monthlySalary;

    // Check if employee started this month and prorate salary
    const startDate = employee.startDate ? new Date(employee.startDate) : null;
    const isNewHireThisMonth = startDate && startDate.getFullYear() === year && startDate.getMonth() === month;

    if (isNewHireThisMonth) {
        let actualWorkingDays = 0;
        const startDayOfMonth = startDate.getDate();
        const date = new Date(year, month, startDayOfMonth);

        while (date.getMonth() === month) {
            const dayOfWeek = date.getDay();
            if (!settings.weekendDays.includes(dayOfWeek)) {
                actualWorkingDays++;
            }
            date.setDate(date.getDate() + 1);
        }
        proratedBaseSalary = dailyRate * actualWorkingDays;
    }


    let overtimePay = 0;
    let undertimeDeduction = 0;
    let absenceDeduction = 0;
    let totalOvertimeHours = 0;
    let totalUndertimeHours = 0;
    let totalAbsenceDays = 0;

    const daysInMonth = new Date(year, month + 1, 0).getDate();

    for (let day = 1; day <= daysInMonth; day++) {
        const currentDate = new Date(year, month, day);

        // If new hire, skip days before start date for attendance calculation
        if (isNewHireThisMonth && currentDate < startDate) {
            continue;
        }

        const dateString = currentDate.toISOString().split('T')[0]; // YYYY-MM-DD
        const dayOfWeek = currentDate.getDay();
        const isWeekend = settings.weekendDays.includes(dayOfWeek);

        const attendanceRecord = employee.attendance.find(a => a.date === dateString);

        if (isWeekend) {
            // Only process if there's an explicit record of work on a weekend
            if (attendanceRecord && attendanceRecord.status !== 'absent') {
                let workedHours = settings.standardDailyHours; // Default for 'present' status on weekend

                if (attendanceRecord.status === 'custom') {
                    if (attendanceRecord.workedHours != null && attendanceRecord.workedHours > 0) {
                        workedHours = attendanceRecord.workedHours;
                    } else if (attendanceRecord.checkIn && attendanceRecord.checkOut) {
                        const [inHours, inMinutes] = attendanceRecord.checkIn.split(':').map(Number);
                        const [outHours, outMinutes] = attendanceRecord.checkOut.split(':').map(Number);
                        const checkInTime = new Date(0,0,0, inHours, inMinutes);
                        const checkOutTime = new Date(0,0,0, outHours, outMinutes);
                        if (checkOutTime < checkInTime) { checkOutTime.setDate(checkOutTime.getDate() + 1); }
                        workedHours = (checkOutTime.getTime() - checkInTime.getTime()) / (1000 * 60 * 60);
                    }
                }

                const overtimeHours = workedHours; // All weekend work is overtime
                if (overtimeHours > 0) {
                    totalOvertimeHours += overtimeHours;
                    overtimePay += overtimeHours * hourlyRate * settings.overtimeMultiplier;
                }
            }
        } else { // It's a working day
            if (attendanceRecord?.status === 'absent') {
                totalAbsenceDays++;
                absenceDeduction += dailyRate * (settings.absenceMultiplier || 1);
            } else if (attendanceRecord?.status === 'custom') {
                let workedHours = 0;
                if (attendanceRecord.workedHours != null && attendanceRecord.workedHours > 0) {
                    workedHours = attendanceRecord.workedHours;
                } else if (attendanceRecord.checkIn && attendanceRecord.checkOut) {
                    const [inHours, inMinutes] = attendanceRecord.checkIn.split(':').map(Number);
                    const [outHours, outMinutes] = attendanceRecord.checkOut.split(':').map(Number);
                    const checkInTime = new Date(0);
                    checkInTime.setHours(inHours, inMinutes, 0, 0);
                    const checkOutTime = new Date(0);
                    checkOutTime.setHours(outHours, outMinutes, 0, 0);

                    if (checkOutTime < checkInTime) { checkOutTime.setDate(checkOutTime.getDate() + 1); }

                    workedHours = (checkOutTime.getTime() - checkInTime.getTime()) / (1000 * 60 * 60);
                }

                if (workedHours > 0) {
                    const overtimeHours = Math.max(0, workedHours - settings.standardDailyHours);
                    const undertimeHours = Math.max(0, settings.standardDailyHours - workedHours);

                    if (overtimeHours > 0) {
                        totalOvertimeHours += overtimeHours;
                        overtimePay += overtimeHours * hourlyRate * settings.overtimeMultiplier;
                    }
                    if (undertimeHours > 0) {
                        totalUndertimeHours += undertimeHours;
                        undertimeDeduction += undertimeHours * hourlyRate * (settings.undertimeMultiplier || 1);
                    }
                }
            }
            // If status is 'present' or no record, it's a normal workday, already accounted for in baseSalary.
        }
    }

    const advanceDeduction = employee.advances.reduce((sum, adv) => {
        const advDate = new Date(adv.date);
        if (advDate.getFullYear() === year && advDate.getMonth() === month) {
            return sum + adv.amount;
        }
        return sum;
    }, 0);

    const finalPay = proratedBaseSalary + overtimePay - absenceDeduction - undertimeDeduction - advanceDeduction;

    return {
        baseSalary: employee.monthlySalary, // Return full salary for display purposes, but use prorated for calculation
        overtimePay,
        undertimeDeduction,
        absenceDeduction,
        advanceDeduction,
        finalPay,
        totalOvertimeHours,
        totalUndertimeHours,
        totalAbsenceDays
    };
};
